// ========== DATA ==========
let ACCOUNTS=[];let DB=null;
function newAccount(){return{id:uid(),user:{email:'',phone:'',password:'',name:'Usuário',avatar:''},lotes:[],inseminacao:[],medDirect:[],aliDirect:[],meta:{lastBackup:0,changes:0}}}
function normalizeAccount(a){if(!a.id)a.id=uid();if(!a.user)a.user={email:'',name:'Usuário',password:'',avatar:''};if(!a.lotes)a.lotes=[];if(!a.inseminacao)a.inseminacao=[];if(!a.medDirect)a.medDirect=[];if(!a.aliDirect)a.aliDirect=[];if(!a.meta)a.meta={lastBackup:0,changes:0};/* migra dados antigos */if(a.rebanhoDirect&&a.rebanhoDirect.length){if(!a.lotes.find(l=>l.name==='Geral'))a.lotes.push({id:uid(),name:'Geral',createdAt:Date.now(),animals:[...a.rebanhoDirect]});a.rebanhoDirect=[]}if(a.rebanho&&a.rebanho.length){a.rebanho.forEach(p=>{if(p.animals&&p.animals.length){const ex=a.lotes.find(l=>l.name===p.name);if(ex){p.animals.forEach(an=>{if(!ex.animals.find(x=>x.id===an.id))ex.animals.push(an)})}else{a.lotes.push({id:p.id||uid(),name:p.name,createdAt:p.createdAt||Date.now(),animals:[...p.animals]})}}});a.rebanho=[]}return a}
const uid=()=>'_'+Math.random().toString(36).slice(2,11);
// Escapa HTML para evitar quebra de layout / injeção ao exibir dados digitados.
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
// Gera hash SHA-256 (hex) da senha. Requer contexto seguro (https ou localhost).
async function hashPass(p){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(p));return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('')}
const isHash=s=>/^[a-f0-9]{64}$/.test(s||'');
function persistAccounts(){try{localStorage.setItem('eltech_users',JSON.stringify(ACCOUNTS))}catch(e){if(e.name==='QuotaExceededError'||e.code===22)toast('Armazenamento cheio! Exporte o backup.','error')}}
function upsertActive(){if(DB&&DB.user&&DB.user.email){const i=ACCOUNTS.findIndex(a=>a.id===DB.id);if(i>=0)ACCOUNTS[i]=DB;else ACCOUNTS.push(DB)}}
const save=()=>{if(DB&&DB.meta)DB.meta.changes=(DB.meta.changes||0)+1;upsertActive();persistAccounts()};
function loadAccounts(){try{const raw=localStorage.getItem('eltech_users');if(raw){ACCOUNTS=JSON.parse(raw)||[]}else{const legacy=localStorage.getItem('eltech_db');if(legacy){const old=JSON.parse(legacy);old.id=old.id||uid();ACCOUNTS=[old]}else{ACCOUNTS=[]}}}catch(e){ACCOUNTS=[]}ACCOUNTS.forEach(normalizeAccount);const activeId=localStorage.getItem('eltech_active');DB=ACCOUNTS.find(a=>a.id===activeId)||ACCOUNTS[0]||newAccount();persistAccounts()}
loadAccounts();

// TOAST
function toast(msg,type='success'){const t=document.getElementById('toast');t.textContent=msg;t.className='toast toast-'+type+' show';setTimeout(()=>t.classList.remove('show'),2800)}

// PASSWORD TOGGLE
function togglePass(id,btn){const input=document.getElementById(id);const isHidden=input.type==='password';input.type=isHidden?'text':'password';btn.innerHTML=isHidden?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>';btn.style.color=isHidden?'var(--g400)':'var(--text3)'}

// CUSTOM CONFIRM
let _confirmCb=null;
function showConfirm(msg,icon='⚠️'){return new Promise(resolve=>{_confirmCb=resolve;document.getElementById('confirmIcon').textContent=icon;document.getElementById('confirmMsg').textContent=msg;document.getElementById('confirmModal').classList.add('show')})}
function confirmResolve(val){document.getElementById('confirmModal').classList.remove('show');if(_confirmCb)_confirmCb(val);_confirmCb=null}

// ========== LOGIN ==========
function switchLoginTab(tab){document.querySelectorAll('.login-tab').forEach((t,i)=>t.classList.toggle('active',['login','register'][i]===tab));document.querySelectorAll('.login-form').forEach(f=>f.classList.remove('active'));document.getElementById(tab==='login'?'loginForm':'registerForm').classList.add('active')}
function isValidEmail(e){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)}
function isValidPassword(p){return p.length>=6&&/[A-Z]/.test(p)&&/[0-9]/.test(p)&&/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(p)}
function isValidName(n){return/^[a-zA-ZÀ-ÿ\s]{1,15}$/.test(n)&&n.trim().length>0}
document.getElementById('regPass').addEventListener('input',function(){const p=this.value;const set=(id,ok)=>{const el=document.getElementById(id);el.style.color=ok?'var(--g400)':'var(--text3)';el.textContent=(ok?'✓ ':'◯ ')+el.textContent.substring(2)};set('reqUpper',/[A-Z]/.test(p));set('reqNumber',/[0-9]/.test(p));set('reqSpecial',/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(p));set('reqLen',p.length>=6)});
async function doLogin(){const input=document.getElementById('loginEmail').value.trim();const p=document.getElementById('loginPass').value;if(!input||!p)return toast('Preencha todos os campos','error');if(!ACCOUNTS.length)return toast('Nenhuma conta cadastrada.','error');const il=input.toLowerCase();let acc=ACCOUNTS.find(a=>a.user.email&&a.user.email.toLowerCase()===il)||ACCOUNTS.find(a=>a.user.name&&a.user.name.toLowerCase()===il);if(!acc)return toast('Usuário não encontrado','error');const stored=acc.user.password;let ok;if(isHash(stored)){ok=(await hashPass(p))===stored}else{/* conta antiga em texto puro: valida e migra para hash */ok=(p===stored);if(ok)acc.user.password=await hashPass(p)}if(!ok)return toast('Senha incorreta','error');DB=acc;localStorage.setItem('eltech_active',acc.id);if(document.getElementById('loginKeep')?.checked){localStorage.setItem('eltech_session','1')}else{localStorage.removeItem('eltech_session')}upsertActive();persistAccounts();enterApp()}
async function doRegister(){const name=document.getElementById('regName').value.trim();const email=document.getElementById('regEmail').value.trim();const pass=document.getElementById('regPass').value;const passConfirm=document.getElementById('regPassConfirm').value;if(!name||!email||!pass||!passConfirm)return toast('Preencha todos os campos','error');if(!isValidName(name))return toast('Nome: apenas letras, máx. 15 caracteres','error');if(!isValidEmail(email))return toast('Email inválido','error');if(!isValidPassword(pass))return toast('Senha precisa de: maiúscula, número e caractere especial','error');if(pass!==passConfirm)return toast('As senhas não coincidem','error');if(ACCOUNTS.some(a=>a.user&&a.user.email&&a.user.email.toLowerCase()===email.toLowerCase()))return toast('Já existe uma conta com este email','error');const acc=newAccount();acc.user={email,name,password:await hashPass(pass),phone:'',avatar:''};ACCOUNTS.push(acc);persistAccounts();['regName','regEmail','regPass','regPassConfirm'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=''});toast('Conta criada! Faça login.');switchLoginTab('login');const le=document.getElementById('loginEmail');if(le)le.value=email}
function enterApp(){document.getElementById('loginPage').classList.add('hidden');document.getElementById('mainApp').style.display='flex';document.getElementById('profileName').value=DB.user.name||'Usuário';if(DB.user.avatar){document.getElementById('avatarImg').src=DB.user.avatar;document.getElementById('avatarImg').style.display='block';document.getElementById('avatarPlaceholder').style.display='none'}renderHome();checkBackupReminder()}
function doLogout(){localStorage.removeItem('eltech_session');currentLoteId=null;editAniId=null;editLoteId=null;currentPlanId=null;editPlanId=null;tempMedAnimals=[];tempAliAnimals=[];tempInsemAnimals=[];document.getElementById('loginPass').value='';document.getElementById('loginPage').classList.remove('hidden');document.getElementById('mainApp').style.display='none'}

// ========== HELPERS ==========
function getAllAnimals(){let all=[];DB.lotes.forEach(l=>l.animals.forEach(a=>all.push({...a,loteId:l.id,loteName:l.name})));return all}
function sortByNum(arr){return arr.sort((a,b)=>{const na=parseInt(a.num)||0;const nb=parseInt(b.num)||0;return na!==nb?na-nb:(a.num||'').localeCompare(b.num||'')})}
function ageMonths(dateStr){if(!dateStr)return'';const d=new Date(dateStr+'T12:00');const now=new Date();let m=(now.getFullYear()-d.getFullYear())*12+(now.getMonth()-d.getMonth());if(now.getDate()<d.getDate())m--;return m<0?0:m}
function ageDays(dateStr){if(!dateStr)return'';return Math.floor((Date.now()-new Date(dateStr+'T12:00').getTime())/(1000*60*60*24))}
function getInsemDate(num){let d='';DB.inseminacao.forEach(p=>p.animals.forEach(a=>{if(a.num===num&&a.data>d)d=a.data}));return d?new Date(d+'T12:00').toLocaleDateString('pt-BR'):''}

// Searchable animal select filter
function filterAnimalSelect(searchId,selectId,type){
  const q=(document.getElementById(searchId)?.value||'').toLowerCase().trim();
  const sel=document.getElementById(selectId);
  const prev=sel.value;
  let animals=[];
  if(type==='insem'){animals=getAllAnimals().filter(a=>a.sexo!=='Macho'&&a.cat!=='Bezerra'&&a.sit!=='Anestro')}
  else{animals=getAllAnimals()}
  sortByNum(animals);
  if(q)animals=animals.filter(a=>(a.num||'').toLowerCase().includes(q)||(a.nome||'').toLowerCase().includes(q));
  sel.innerHTML='<option value="">Selecione...</option>';
  animals.forEach(a=>{sel.innerHTML+=`<option value="${esc(a.num)}|${esc(a.nome)}">#${esc(a.num)} - ${esc(a.nome)} (${esc(a.loteName||'')})</option>`});
  if(prev){sel.value=prev}
}

// ========== NAV ==========
let currentLoteId=null;let editAniId=null;let editLoteId=null;
function refreshCurrentPage(){const a=document.querySelector('.page.active');if(!a)return;const id=a.id;if(id==='pageHome')renderHome();else if(id==='pageRebanho'){if(!document.getElementById('loteDetail').classList.contains('hidden'))renderLoteAnimals();else renderLotes()}else if(id==='pageInseminacao'){if(!document.getElementById('insemDetail').classList.contains('hidden'))renderAnimals('inseminacao');else renderPlanilhas('inseminacao')}else if(id==='pageMedicacao')renderMedDirect();else if(id==='pageAlimentacao')renderAliDirect();else if(id==='pageRelatorios')populateReportSources();toast('Atualizado!','info')}
function goPage(id){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===id));document.querySelector('.page-content').scrollTop=0;if(id==='pageHome')renderHome();if(id==='pageRebanho'){document.getElementById('rebanhoMain').classList.remove('hidden');document.getElementById('loteDetail').classList.add('hidden');renderLotes()}if(id==='pageInseminacao'){document.getElementById('insemList').classList.remove('hidden');document.getElementById('insemDetail').classList.add('hidden');renderPlanilhas('inseminacao')}if(id==='pageMedicacao')renderMedDirect();if(id==='pageAlimentacao')renderAliDirect();if(id==='pageRelatorios')populateReportSources()}

// ========== MODAL ==========
function openModal(id){document.getElementById(id).classList.add('show');if(id==='animalModal'&&!editAniId){document.getElementById('animalModalTitle').textContent='Adicionar Animal';initAnimalForm();populateLoteSelect('animalLote')}if(id==='loteModal'&&!editLoteId)document.getElementById('loteModalTitle').textContent='Novo Lote';if(id==='medAnimalModal'){populateMedLoteSelect();populateMedSelect();medMode='lote';setMedMode('lote')}if(id==='aliAnimalModal'){populateAliLoteSelect();populateAliAnimalSelect2();aliMode='lote';setAliMode('lote')}if(id==='insemAnimalModal'){populateInsemPlanSelect();populateInsemSelect()}}
function closeModal(id){document.getElementById(id).classList.remove('show');editAniId=null;editLoteId=null;editPlanId=null;tempMedAnimals=[];tempAliAnimals=[];tempInsemAnimals=[];document.getElementById(id).querySelectorAll('input:not([type=file]):not([disabled]):not([type=checkbox]),textarea').forEach(el=>el.value='');document.getElementById(id).querySelectorAll('select').forEach(el=>el.selectedIndex=0);if(id==='aliAnimalModal'){const as=document.getElementById('aliSelectedAnimals');if(as)as.innerHTML='';document.querySelectorAll('#dietaChecks input[type=checkbox]').forEach(cb=>cb.checked=false);const df=document.getElementById('dietDetailFields');if(df)df.innerHTML='';const cp=document.getElementById('aliCostPreview');if(cp)cp.innerHTML='';const la=document.getElementById('aliLoteAnimals');if(la)la.innerHTML=''}if(id==='medAnimalModal'){const la=document.getElementById('medLoteAnimals');if(la)la.innerHTML='';const ms=document.getElementById('medSelectedAnimals');if(ms)ms.innerHTML=''}if(id==='insemAnimalModal'){const is=document.getElementById('insemSelectedAnimals');if(is)is.innerHTML=''}}

// ========== LOTES ==========
function populateLoteSelect(selId){const sel=document.getElementById(selId);if(!sel)return;const prev=sel.value;sel.innerHTML='<option value="">Selecione...</option>';DB.lotes.forEach(l=>{sel.innerHTML+=`<option value="${l.id}">${esc(l.name)} (${l.animals.length})</option>`});if(prev)sel.value=prev}
function saveLote(){const name=document.getElementById('loteNome').value.trim();if(!name)return toast('Digite o nome do lote','error');if(editLoteId){const l=DB.lotes.find(x=>x.id===editLoteId);if(l)l.name=name}else DB.lotes.push({id:uid(),name,createdAt:Date.now(),animals:[]});save();closeModal('loteModal');renderLotes();toast('Lote salvo!')}
function renderLotes(){const container=document.getElementById('lotesList');const sorted=[...DB.lotes].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));container.innerHTML=sorted.length?sorted.map(l=>{return`<div class="card glass2 anim-fade"><div style="display:flex;justify-content:space-between;align-items:flex-start"><div><div class="card-title">${esc(l.name)}</div><div class="card-sub">${l.animals.length} animal(is)</div></div></div><div class="card-actions"><button class="edit-btn" onclick="event.stopPropagation();editLoteFromCard('${l.id}')">Editar</button><button class="del-btn" onclick="event.stopPropagation();delLote('${l.id}')">Excluir</button><button class="open-btn" onclick="openLoteDetail('${l.id}')">Abrir →</button></div></div>`}).join(''):'<div class="empty-state"><p>Nenhum lote criado.</p></div>'}
function editLoteFromCard(id){const l=DB.lotes.find(x=>x.id===id);if(!l)return;editLoteId=id;document.getElementById('loteNome').value=l.name;document.getElementById('loteModalTitle').textContent='Editar Lote';openModal('loteModal')}
async function delLote(id){const ok=await showConfirm('Excluir este lote e todos os animais?','🗑️');if(!ok)return;DB.lotes=DB.lotes.filter(x=>x.id!==id);save();renderLotes();toast('Lote excluído')}
function openLoteDetail(id){currentLoteId=id;document.getElementById('rebanhoMain').classList.add('hidden');document.getElementById('loteDetail').classList.remove('hidden');const l=DB.lotes.find(x=>x.id===id);document.getElementById('loteDetailTitle').textContent=l.name;if(document.getElementById('searchLote'))document.getElementById('searchLote').value='';renderLoteAnimals()}
function backToLotes(){document.getElementById('loteDetail').classList.add('hidden');document.getElementById('rebanhoMain').classList.remove('hidden');renderLotes()}
function openAnimalForLote(){editAniId=null;document.getElementById('animalModalTitle').textContent='Adicionar Animal';initAnimalForm();populateLoteSelect('animalLote');document.getElementById('animalLote').value=currentLoteId||'';openModal('animalModal')}
function toggleLoteFilter(){document.getElementById('loteFilterBar').classList.toggle('hidden')}

function renderLoteAnimals(){const l=DB.lotes.find(x=>x.id===currentLoteId);if(!l)return;let animals=[...l.animals];const q=(document.getElementById('searchLote')?.value||'').toLowerCase().trim();if(q)animals=animals.filter(a=>(a.num||'').toLowerCase().includes(q)||(a.nome||'').toLowerCase().includes(q));const fs=document.getElementById('filterSexo')?.value||'';const fc=document.getElementById('filterCat')?.value||'';const fst=document.getElementById('filterSit')?.value||'';if(fs)animals=animals.filter(a=>a.sexo===fs);if(fc)animals=animals.filter(a=>a.cat===fc);if(fst)animals=animals.filter(a=>a.sit===fst);sortByNum(animals);const container=document.getElementById('loteAnimals');if(!animals.length){container.innerHTML=`<div class="empty-state"><p>${q||fs||fc||fst?'Nenhum resultado.':'Nenhum animal neste lote.'}</p></div>`;return}container.innerHTML=animals.map((a,i)=>{const insem=getInsemDate(a.num);const age=ageMonths(a.dataNasc);const parto=a.ultimoParto?ageDays(a.ultimoParto)+' dias':'';const prenha=a.prenhaData?ageDays(a.prenhaData)+' dias de prenhez':'';let details=[];if(a.raca)details.push('Raça: '+esc(a.raca));if(a.peso)details.push('Peso: '+esc(a.peso)+'kg');if(a.leite)details.push('Leite: '+esc(a.leite)+'L/dia');if(a.nomeMae)details.push('Mãe: '+esc(a.nomeMae));if(a.nomePai)details.push('Pai: '+esc(a.nomePai));let details2=[];if(insem)details2.push('Insem: '+insem);if(parto)details2.push('Parto: '+parto);if(prenha)details2.push(prenha);return`<div class="animal-row" style="animation-delay:${i*0.03}s"><div class="ani-thumb" data-aid="${a.id}" onclick="openFicha('${a.id}')">🐄</div><div class="animal-info" style="cursor:pointer" onclick="openFicha('${a.id}')"><div><span class="num">#${esc(a.num)}</span><span class="name-text">${esc(a.nome)}</span>${age?`<span style="font-size:.68rem;color:var(--text3);margin-left:6px">${age} meses</span>`:''}</div><div class="badges"><span class="badge ${a.sexo==='Macho'?'badge-m':'badge-f'}">${esc(a.sexo)}</span><span class="badge badge-cat">${esc(a.cat)}</span><span class="badge badge-sit">${esc(a.sit)}</span>${a.origem?`<span class="badge badge-muco">${esc(a.origem)}</span>`:''}</div>${details.length?`<div class="detail">${details.join(' · ')}</div>`:''}${details2.length?`<div class="detail">${details2.join(' · ')}</div>`:''}</div><div class="animal-actions"><button class="edit-btn" style="background:var(--info);color:#fff" onclick="openHist('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 3v18h18"/><path d="M7 14l4-4 3 3 5-6"/></svg></button><button class="edit-btn" onclick="editAnimalInLote('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button><button class="del-btn" onclick="delAnimalFromLote('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 6h18M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2"/></svg></button></div></div>`}).join('');hydrateThumbs()}

// ========== ANIMAL FORM ==========
function onSexoChange(){const sexo=document.getElementById('animalSexo').value;const catSel=document.getElementById('animalCat');catSel.innerHTML='';if(sexo==='Macho'){['Bezerro','Garrote','Boi','Touro'].forEach(o=>{catSel.innerHTML+=`<option value="${o}">${o}</option>`})}else{['Bezerra','Novilha','Vaca seca','Vaca em lactação'].forEach(o=>{catSel.innerHTML+=`<option value="${o}">${o}</option>`})}onCatChange()}
function onCatChange(){const sexo=document.getElementById('animalSexo').value;const cat=document.getElementById('animalCat').value;const sitSel=document.getElementById('animalSit');if(sexo==='Macho'||cat==='Bezerra'){sitSel.innerHTML='<option value="Não se aplica">Não se aplica</option>';sitSel.disabled=true}else{sitSel.innerHTML='';['Anestro','Vazia','Prenha'].forEach(o=>{sitSel.innerHTML+=`<option value="${o}">${o}</option>`});sitSel.disabled=false}onSitChange()}
function onSitChange(){updateFieldVisibility()}
function updateFieldVisibility(){const sexo=document.getElementById('animalSexo').value;const cat=document.getElementById('animalCat').value;const sit=document.getElementById('animalSit').value;const hideLeite=(sexo==='Macho'||cat==='Bezerro'||cat==='Bezerra'||sit==='Anestro');document.getElementById('leiteGroup').style.display=hideLeite?'none':'block';if(hideLeite)document.getElementById('animalLeite').value='';const showParto=(sexo==='Fêmea'&&(cat==='Novilha'||cat==='Vaca seca'||cat==='Vaca em lactação')&&(sit==='Vazia'||sit==='Prenha'));document.getElementById('partoGroup').style.display=showParto?'block':'none';if(!showParto)document.getElementById('animalUltimoParto').value='';const showPrenha=(sit==='Prenha');document.getElementById('prenhaGroup').style.display=showPrenha?'block':'none';if(!showPrenha){document.getElementById('animalPrenhaData').value='';document.getElementById('animalPrenhaDias').value=''}}
function initAnimalForm(){onSexoChange();onOrigemChange();resetAnimalPhoto()}
function onOrigemChange(){const origem=document.getElementById('animalOrigem').value;document.getElementById('paiMaeNascido').classList.toggle('hidden',origem!=='Nascido');document.getElementById('paiMaeComprado').classList.toggle('hidden',origem!=='Comprado');if(origem==='Nascido')populateMaePaiSelects()}
function populateMaePaiSelects(){const all=getAllAnimals();const maeSel=document.getElementById('animalMaeSelect');const paiSel=document.getElementById('animalPaiSelect');const prevMae=maeSel.value;const prevPai=paiSel.value;maeSel.innerHTML='<option value="">Selecione...</option>';paiSel.innerHTML='<option value="">Selecione...</option>';sortByNum(all.filter(a=>a.sexo==='Fêmea')).forEach(a=>{maeSel.innerHTML+=`<option value="${esc(a.nome)}">#${esc(a.num)} - ${esc(a.nome)}</option>`});/* Pais: machos do rebanho + touros da inseminação */const pais=new Set();sortByNum(all.filter(a=>a.sexo==='Macho')).forEach(a=>{paiSel.innerHTML+=`<option value="${esc(a.nome)}">#${esc(a.num)} - ${esc(a.nome)}</option>`;pais.add(a.nome)});DB.inseminacao.forEach(p=>p.animals.forEach(a=>{if(a.touro&&!pais.has(a.touro)){paiSel.innerHTML+=`<option value="${esc(a.touro)}">🧬 ${esc(a.touro)} (insem.)</option>`;pais.add(a.touro)}}));if(prevMae)maeSel.value=prevMae;if(prevPai)paiSel.value=prevPai}

function saveAnimalToLote(){let savedAid=editAniId||null;const num=document.getElementById('animalNum').value.trim();const nome=document.getElementById('animalNome').value.trim();const loteId=document.getElementById('animalLote').value;if(!num||!nome)return toast('Preencha nº e nome','error');if(!loteId)return toast('Selecione um lote','error');if(!editAniId){const chkLote=DB.lotes.find(x=>x.id===loteId);if(chkLote&&chkLote.animals.find(x=>x.num===num))return toast('Nº '+num+' já existe neste lote','error');}const origem=document.getElementById('animalOrigem').value;let nomeMae='',nomePai='',tipoPrenhez='';if(origem==='Nascido'){nomeMae=document.getElementById('animalMaeSelect').value||'';nomePai=document.getElementById('animalPaiSelect').value||'';tipoPrenhez=document.getElementById('animalTipoPrenhez').value||''}else{nomeMae=document.getElementById('animalNomeMae').value.trim();nomePai=document.getElementById('animalNomePai').value.trim()}const newPeso=document.getElementById('animalPeso').value||'';let prenhaData=document.getElementById('animalPrenhaData').value||'';const prenhaDias=document.getElementById('animalPrenhaDias').value||'';if(!prenhaData&&prenhaDias){const dias=parseInt(prenhaDias,10);if(!isNaN(dias)){const d=new Date();d.setDate(d.getDate()-dias);prenhaData=d.toISOString().split('T')[0]}}const d={num,nome,origem,tipoPrenhez,dataNasc:document.getElementById('animalDataNasc').value||'',sexo:document.getElementById('animalSexo').value,cat:document.getElementById('animalCat').value,sit:document.getElementById('animalSit').value,raca:document.getElementById('animalRaca').value||'',nomeMae,nomePai,peso:newPeso,leite:document.getElementById('animalLeite').value||'',ultimoParto:document.getElementById('animalUltimoParto').value||'',prenhaData};if(editAniId){let oldAnimal=null;DB.lotes.forEach(l=>{const f=l.animals.find(x=>x.id===editAniId);if(f)oldAnimal=f});if(oldAnimal){/* weight history */if(newPeso&&newPeso!==oldAnimal.peso){if(!oldAnimal.pesagens)oldAnimal.pesagens=[];oldAnimal.pesagens.push({peso:newPeso,data:new Date().toISOString().split('T')[0]});if(oldAnimal.pesagens.length>5)oldAnimal.pesagens=oldAnimal.pesagens.slice(-5);d.pesagens=oldAnimal.pesagens}else{d.pesagens=oldAnimal.pesagens||[]}const nl=d.leite;if(nl&&nl!==oldAnimal.leite){if(!oldAnimal.leiteHist)oldAnimal.leiteHist=[];oldAnimal.leiteHist.push({leite:nl,data:new Date().toISOString().split('T')[0]});if(oldAnimal.leiteHist.length>20)oldAnimal.leiteHist=oldAnimal.leiteHist.slice(-20);d.leiteHist=oldAnimal.leiteHist}else{d.leiteHist=oldAnimal.leiteHist||[]}}let found=false;DB.lotes.forEach(l=>{const idx=l.animals.findIndex(x=>x.id===editAniId);if(idx!==-1){if(l.id===loteId){Object.assign(l.animals[idx],d);found=true}else{const[removed]=l.animals.splice(idx,1);Object.assign(removed,d);const target=DB.lotes.find(x=>x.id===loteId);if(target){target.animals.push(removed);found=true}}}})}else{d.pesagens=newPeso?[{peso:newPeso,data:new Date().toISOString().split('T')[0]}]:[];d.leiteHist=d.leite?[{leite:d.leite,data:new Date().toISOString().split('T')[0]}]:[];const lote=DB.lotes.find(x=>x.id===loteId);const _nid=uid();if(lote){lote.animals.push({id:_nid,...d});savedAid=_nid}/* Auto-update mãe: set ultimoParto and change sit to Vazia */if(origem==='Nascido'&&nomeMae&&d.dataNasc){DB.lotes.forEach(l=>{l.animals.forEach(a=>{if(a.nome===nomeMae&&a.sexo==='Fêmea'){a.ultimoParto=d.dataNasc;if(a.sit==='Prenha')a.sit='Vazia';a.prenhaData=''}})})}}save();if(savedAid&&tempAnimalPhoto!==undefined){(tempAnimalPhoto?photoPut(savedAid,tempAnimalPhoto):photoDel(savedAid)).then(()=>{if(currentLoteId)renderLoteAnimals()})}closeModal('animalModal');if(currentLoteId)renderLoteAnimals();renderLotes();toast('Animal salvo!')}
function editAnimalInLote(aid){let a=null;let srcLoteId='';DB.lotes.forEach(l=>{const f=l.animals.find(x=>x.id===aid);if(f){a=f;srcLoteId=l.id}});if(!a)return;editAniId=aid;populateLoteSelect('animalLote');document.getElementById('animalNum').value=a.num;document.getElementById('animalNome').value=a.nome;document.getElementById('animalOrigem').value=a.origem||'Nascido';onOrigemChange();if(a.origem==='Nascido'){document.getElementById('animalTipoPrenhez').value=a.tipoPrenhez||'Natural';document.getElementById('animalMaeSelect').value=a.nomeMae||'';document.getElementById('animalPaiSelect').value=a.nomePai||''}else{document.getElementById('animalNomeMae').value=a.nomeMae||'';document.getElementById('animalNomePai').value=a.nomePai||''}document.getElementById('animalDataNasc').value=a.dataNasc||'';document.getElementById('animalLote').value=srcLoteId;document.getElementById('animalSexo').value=a.sexo;onSexoChange();document.getElementById('animalCat').value=a.cat;onCatChange();document.getElementById('animalSit').value=a.sit;updateFieldVisibility();document.getElementById('animalRaca').value=a.raca||'';document.getElementById('animalPeso').value=a.peso||'';document.getElementById('animalLeite').value=a.leite||'';document.getElementById('animalUltimoParto').value=a.ultimoParto||'';document.getElementById('animalPrenhaData').value=a.prenhaData||'';document.getElementById('animalPrenhaDias').value='';document.getElementById('animalModalTitle').textContent='Editar Animal';tempAnimalPhoto=undefined;const _pi=document.getElementById('animalPhotoInput');if(_pi)_pi.value='';photoGet(aid).then(d=>setAnimalPhotoUI(d||null));openModal('animalModal')}
async function delAnimalFromLote(aid){const ok=await showConfirm('Excluir este animal?','🗑️');if(!ok)return;DB.lotes.forEach(l=>{l.animals=l.animals.filter(x=>x.id!==aid)});photoDel(aid);save();renderLoteAnimals();toast('Animal excluído')}

// ========== INSEMINAÇÃO ==========
function renderPlanilhas(type){if(type!=='inseminacao')return;const el=document.getElementById('insemPlanilhas');const sorted=[...DB.inseminacao].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));el.innerHTML=sorted.length?sorted.map(p=>{const dateStr=p.createdAt?new Date(p.createdAt).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'}):'';return`<div class="card glass2 anim-fade"><div class="card-title">${esc(p.name)}</div><div class="card-sub">${p.animals.length} registro(s)${dateStr?' · '+dateStr:''}</div><div class="card-actions"><button class="edit-btn" onclick="event.stopPropagation();editPlanFromCard('${p.id}')">Editar</button><button class="del-btn" onclick="event.stopPropagation();delPlan('${p.id}')">Excluir</button><button class="open-btn" onclick="openInsemDetail('${p.id}')">Abrir →</button></div></div>`}).join(''):'<div class="empty-state"><p>Nenhuma planilha criada.</p></div>'}
let editPlanId=null;let currentPlanId=null;
function editPlanFromCard(id){const p=DB.inseminacao.find(x=>x.id===id);if(!p)return;editPlanId=id;document.getElementById('planilhaNome').value=p.name;document.getElementById('planilhaModalTitle').textContent='Editar Planilha';openModal('planilhaModal')}
function savePlanilha(){const name=document.getElementById('planilhaNome').value.trim();if(!name)return toast('Digite o nome','error');if(editPlanId){const p=DB.inseminacao.find(x=>x.id===editPlanId);if(p)p.name=name}else DB.inseminacao.push({id:uid(),name,animals:[],createdAt:Date.now()});save();closeModal('planilhaModal');editPlanId=null;renderPlanilhas('inseminacao');toast('Planilha salva!')}
async function delPlan(id){const ok=await showConfirm('Excluir esta planilha?','🗑️');if(!ok)return;DB.inseminacao=DB.inseminacao.filter(x=>x.id!==id);save();renderPlanilhas('inseminacao');toast('Excluída')}
function openInsemDetail(id){currentPlanId=id;document.getElementById('insemList').classList.add('hidden');document.getElementById('insemDetail').classList.remove('hidden');const p=DB.inseminacao.find(x=>x.id===id);document.getElementById('insemDetailTitle').textContent=p.name;if(document.getElementById('searchInseminacao'))document.getElementById('searchInseminacao').value='';renderAnimals('inseminacao')}
function backToList(){document.getElementById('insemDetail').classList.add('hidden');document.getElementById('insemList').classList.remove('hidden');renderPlanilhas('inseminacao')}
function renderAnimals(type){if(type!=='inseminacao')return;const p=DB.inseminacao.find(x=>x.id===currentPlanId);if(!p)return;const container=document.getElementById('insemAnimals');let animals=[...p.animals];const q=(document.getElementById('searchInseminacao')?.value||'').toLowerCase().trim();if(q)animals=animals.filter(a=>(a.num||'').toLowerCase().includes(q)||(a.nome||'').toLowerCase().includes(q));sortByNum(animals);if(!animals.length){container.innerHTML=`<div class="empty-state"><p>${q?'Nenhum resultado.':'Nenhum registro.'}</p></div>`;return}container.innerHTML=animals.map((a,i)=>{let details=[];if(a.data)details.push('Data: '+new Date(a.data+'T12:00').toLocaleDateString('pt-BR'));if(a.touro)details.push('Touro: '+esc(a.touro));let badges=[];if(a.muco)badges.push(`<span class="badge badge-muco">Muco: ${esc(a.muco)}</span>`);if(a.tempo)badges.push(`<span class="badge badge-cat">${esc(a.tempo)}</span>`);return`<div class="animal-row" style="animation-delay:${i*0.03}s"><div class="animal-info"><div><span class="num">#${esc(a.num)}</span><span class="name-text">${esc(a.nome)}</span></div>${details.length?`<div class="detail">${details.join(' · ')}</div>`:''}${badges.length?`<div class="badges">${badges.join('')}</div>`:''}${a.obs?`<div class="detail" style="font-style:italic;margin-top:3px">${esc(a.obs)}</div>`:''}</div><div class="animal-actions"><button class="edit-btn" onclick="editInsemAnimal('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button><button class="del-btn" onclick="delInsemAnimal('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 6h18M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2"/></svg></button></div></div>`}).join('')}
function populateInsemSelect(){const sel=document.getElementById('insemAnimalSelect');sel.innerHTML='<option value="">Selecione o animal...</option>';const eligible=getAllAnimals().filter(a=>a.sexo!=='Macho'&&a.cat!=='Bezerra'&&a.sit!=='Anestro');sortByNum(eligible);eligible.forEach(a=>{sel.innerHTML+=`<option value="${esc(a.num)}|${esc(a.nome)}">#${esc(a.num)} - ${esc(a.nome)}</option>`})}
function populateInsemPlanSelect(){const sel=document.getElementById('insemPlanSelect');const prev=sel.value;sel.innerHTML='<option value="">Selecione a planilha...</option>';DB.inseminacao.forEach(p=>{sel.innerHTML+=`<option value="${p.id}">${esc(p.name)}</option>`});if(prev)sel.value=prev}
function openInsemAnimalDirect(){editAniId=null;tempInsemAnimals=[];populateInsemPlanSelect();populateInsemSelect();document.getElementById('insemAnimalModalTitle').textContent='Adicionar Inseminação';openModal('insemAnimalModal')}
function openInsemAnimalForPlan(){editAniId=null;tempInsemAnimals=[];populateInsemPlanSelect();populateInsemSelect();document.getElementById('insemPlanSelect').value=currentPlanId||'';document.getElementById('insemAnimalModalTitle').textContent='Adicionar Inseminação';openModal('insemAnimalModal')}
let tempInsemAnimals=[];
function addInsemAnimal(){const sel=document.getElementById('insemAnimalSelect');if(!sel.value)return;const[num,nome]=sel.value.split('|');if(tempInsemAnimals.find(a=>a.num===num))return toast('Já adicionado','info');tempInsemAnimals.push({num,nome});renderTempInsemAnimals();sel.selectedIndex=0}
function renderTempInsemAnimals(){document.getElementById('insemSelectedAnimals').innerHTML=tempInsemAnimals.map((a,i)=>`<span class="badge badge-cat" style="cursor:pointer;padding:5px 12px" onclick="tempInsemAnimals.splice(${i},1);renderTempInsemAnimals()">#${esc(a.num)} ${esc(a.nome)} ✕</span>`).join('')}
function saveInsemAnimal(){const planId=document.getElementById('insemPlanSelect').value;if(!planId)return toast('Selecione uma planilha','error');const p=DB.inseminacao.find(x=>x.id===planId);if(!p)return toast('Planilha não encontrada','error');let animalsToSave=[];if(editAniId){const ex=p.animals.find(x=>x.id===editAniId);if(ex)animalsToSave=[{num:ex.num,nome:ex.nome}];const sel=document.getElementById('insemAnimalSelect');if(sel.value){const[num,nome]=sel.value.split('|');animalsToSave=[{num,nome}]}}else{animalsToSave=[...tempInsemAnimals];if(!animalsToSave.length){const sel=document.getElementById('insemAnimalSelect');if(sel.value){const[num,nome]=sel.value.split('|');animalsToSave=[{num,nome}]}}}if(!animalsToSave.length)return toast('Adicione ao menos um animal','error');const base={data:document.getElementById('insemData').value,tempo:document.getElementById('insemTempo').value,touro:document.getElementById('insemTouro').value,muco:document.getElementById('insemMuco').value,obs:document.getElementById('insemObs').value};if(editAniId){const a=p.animals.find(x=>x.id===editAniId);if(a)Object.assign(a,{...base,num:animalsToSave[0].num,nome:animalsToSave[0].nome,aid:resolveAid(animalsToSave[0].num)})}else{animalsToSave.forEach(an=>{p.animals.push({id:uid(),num:an.num,nome:an.nome,aid:resolveAid(an.num),...base})})}tempInsemAnimals=[];save();closeModal('insemAnimalModal');if(currentPlanId===planId)renderAnimals('inseminacao');renderPlanilhas('inseminacao');toast('Inseminação salva!')}
function editInsemAnimal(aid){const p=DB.inseminacao.find(x=>x.id===currentPlanId);const a=p.animals.find(x=>x.id===aid);if(!a)return;editAniId=aid;populateInsemPlanSelect();populateInsemSelect();document.getElementById('insemPlanSelect').value=currentPlanId;document.getElementById('insemAnimalSelect').value=a.num+'|'+a.nome;document.getElementById('insemData').value=a.data;document.getElementById('insemTempo').value=a.tempo;document.getElementById('insemTouro').value=a.touro;document.getElementById('insemMuco').value=a.muco;document.getElementById('insemObs').value=a.obs;document.getElementById('insemAnimalModalTitle').textContent='Editar';openModal('insemAnimalModal')}
async function delInsemAnimal(aid){const ok=await showConfirm('Excluir?','🗑️');if(!ok)return;const p=DB.inseminacao.find(x=>x.id===currentPlanId);p.animals=p.animals.filter(x=>x.id!==aid);save();renderAnimals('inseminacao');toast('Excluído')}

// ========== MEDICAÇÃO (lote + individual, grouped records) ==========
let medMode='lote';let tempMedAnimals=[];
function setMedMode(mode){medMode=mode;document.getElementById('medModeLote').classList.toggle('active',mode==='lote');document.getElementById('medModeIndiv').classList.toggle('active',mode==='individual');document.getElementById('medLoteSection').classList.toggle('hidden',mode!=='lote');document.getElementById('medIndivSection').classList.toggle('hidden',mode!=='individual')}
function populateMedLoteSelect(){const sel=document.getElementById('medLoteSelect');sel.innerHTML='<option value="">Selecione o lote...</option>';DB.lotes.forEach(l=>{sel.innerHTML+=`<option value="${l.id}">${esc(l.name)} (${l.animals.length})</option>`})}
function populateMedSelect(){const sel=document.getElementById('medAnimalSelect');sel.innerHTML='<option value="">Selecione o animal...</option>';const all=sortByNum(getAllAnimals().slice());all.forEach(a=>{sel.innerHTML+=`<option value="${esc(a.num)}|${esc(a.nome)}">#${esc(a.num)} - ${esc(a.nome)} (${esc(a.loteName)})</option>`})}
function loadMedLoteAnimals(){const lid=document.getElementById('medLoteSelect').value;const container=document.getElementById('medLoteAnimals');if(!lid){container.innerHTML='';tempMedAnimals=[];return}const l=DB.lotes.find(x=>x.id===lid);if(!l)return;tempMedAnimals=l.animals.map(a=>({num:a.num,nome:a.nome,included:true}));renderMedLoteList()}
function renderMedLoteList(){const container=document.getElementById('medLoteAnimals');container.innerHTML=tempMedAnimals.map((a,i)=>`<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;border-radius:6px;margin-bottom:4px;background:${a.included?'rgba(78,232,152,0.1)':'rgba(255,87,87,0.08)'}"><label style="display:flex;align-items:center;gap:6px;cursor:pointer;flex:1;font-size:.8rem;color:${a.included?'var(--g300)':'var(--danger)'}"><input type="checkbox" ${a.included?'checked':''} onchange="tempMedAnimals[${i}].included=this.checked;renderMedLoteList()" style="accent-color:var(--g500)">#${esc(a.num)} ${esc(a.nome)}</label></div>`).join('')}
function addMedAnimalIndiv(){const sel=document.getElementById('medAnimalSelect');if(!sel.value)return;const[num,nome]=sel.value.split('|');if(tempMedAnimals.find(a=>a.num===num))return toast('Já adicionado','info');tempMedAnimals.push({num,nome,included:true});renderMedIndivList();sel.selectedIndex=0}
function renderMedIndivList(){document.getElementById('medSelectedAnimals').innerHTML=tempMedAnimals.map((a,i)=>`<span class="badge badge-cat" style="cursor:pointer;padding:5px 12px" onclick="tempMedAnimals.splice(${i},1);renderMedIndivList()">#${esc(a.num)} ${esc(a.nome)} ✕</span>`).join('')}
function addMedRow(){const container=document.getElementById('medMedicamentos');container.innerHTML+=`<div class="flex-row med-row" style="margin-bottom:8px"><div class="form-group" style="margin-bottom:0;flex:2"><input class="form-input medNomeInput" placeholder="Nome"></div><div class="form-group" style="margin-bottom:0;flex:1"><input class="form-input medDoseInput" placeholder="Dose"></div><button onclick="this.parentElement.remove()" style="background:none;border:none;color:var(--danger);cursor:pointer;padding:4px;align-self:flex-end;margin-bottom:4px;font-size:1.2rem">✕</button></div>`}
function getMedRows(){const rows=[];document.querySelectorAll('#medMedicamentos .med-row').forEach(r=>{const nome=r.querySelector('.medNomeInput').value.trim();const dose=r.querySelector('.medDoseInput').value.trim();if(nome)rows.push({nome,dose})});return rows}
function setMedRows(meds){const container=document.getElementById('medMedicamentos');container.innerHTML='';(meds||[]).forEach((m,i)=>{container.innerHTML+=`<div class="flex-row med-row" style="margin-bottom:8px"><div class="form-group" style="margin-bottom:0;flex:2">${i===0?'<label style="font-size:.65rem">Medicamento</label>':''}<input class="form-input medNomeInput" placeholder="Nome" value="${esc(m.nome||'')}"></div><div class="form-group" style="margin-bottom:0;flex:1">${i===0?'<label style="font-size:.65rem">Dosagem</label>':''}<input class="form-input medDoseInput" placeholder="Dose" value="${esc(m.dose||'')}"></div>${i>0?'<button onclick="this.parentElement.remove()" style="background:none;border:none;color:var(--danger);cursor:pointer;padding:4px;align-self:flex-end;margin-bottom:4px;font-size:1.2rem">✕</button>':''}</div>`});if(!meds||!meds.length)container.innerHTML=`<div class="flex-row med-row" style="margin-bottom:8px"><div class="form-group" style="margin-bottom:0;flex:2"><label style="font-size:.65rem">Medicamento</label><input class="form-input medNomeInput" placeholder="Nome"></div><div class="form-group" style="margin-bottom:0;flex:1"><label style="font-size:.65rem">Dosagem</label><input class="form-input medDoseInput" placeholder="Dose"></div></div>`}
function saveMedAnimal(){let animalsToSave=[];if(medMode==='lote'){animalsToSave=tempMedAnimals.filter(a=>a.included)}else{animalsToSave=tempMedAnimals.filter(a=>a.included!==false);if(!animalsToSave.length){const sel=document.getElementById('medAnimalSelect');if(sel.value){const[num,nome]=sel.value.split('|');animalsToSave=[{num,nome}]}}}if(!animalsToSave.length)return toast('Adicione ao menos um animal','error');const meds=getMedRows();if(!meds.length)return toast('Adicione ao menos um medicamento','error');const base={dataIni:document.getElementById('medDataIni').value,dataFim:document.getElementById('medDataFim').value,tipo:document.getElementById('medTipo').value,carenciaLeite:document.getElementById('medCarLeite').value||'',carenciaCarne:document.getElementById('medCarCarne').value||'',medicamentos:meds};if(editAniId){const rec=DB.medDirect.find(x=>x.id===editAniId);if(rec)Object.assign(rec,{...base,animais:animalsToSave.map(a=>({num:a.num,nome:a.nome,aid:a.aid||resolveAid(a.num)}))})}else{DB.medDirect.push({id:uid(),...base,animais:animalsToSave.map(a=>({num:a.num,nome:a.nome,aid:a.aid||resolveAid(a.num)}))})}save();closeModal('medAnimalModal');renderMedDirect();toast('Medicação salva!')}
function renderMedDirect(){const container=document.getElementById('medDirectList');const q=(document.getElementById('searchMedicacao')?.value||'').toLowerCase().trim();let items=[...DB.medDirect];if(q)items=items.filter(a=>{if(a.animais)return a.animais.some(x=>(x.num||'').toLowerCase().includes(q)||(x.nome||'').toLowerCase().includes(q));return(a.num||'').toLowerCase().includes(q)||(a.nome||'').toLowerCase().includes(q)});if(!items.length){container.innerHTML=`<div class="empty-state"><p>${q?'Nenhum resultado.':'Nenhuma medicação registrada.'}</p></div>`;return}container.innerHTML=items.map((a,i)=>{const animals=a.animais||[{num:a.num,nome:a.nome}];const animalBadges=animals.map(x=>`<span class="badge badge-cat" style="margin:1px">#${esc(x.num)} ${esc(x.nome)}</span>`).join('');const meds=a.medicamentos;let medStr='';if(Array.isArray(meds)){medStr=meds.map(m=>{let s='<strong>'+esc(m.nome)+'</strong>';if(m.dose)s+=' · '+esc(m.dose);return s}).join('<br>')}else if(typeof meds==='string'&&meds){medStr=esc(meds)}else if(a.nomeMed){medStr='<strong>'+esc(a.nomeMed)+'</strong>';if(a.dosagem)medStr+=' · '+esc(a.dosagem)}let dateStr='';if(a.dataIni)dateStr+='De '+new Date(a.dataIni+'T12:00').toLocaleDateString('pt-BR');if(a.dataFim)dateStr+=' até '+new Date(a.dataFim+'T12:00').toLocaleDateString('pt-BR');let carStr='';if(a.carenciaLeite)carStr+='🥛 carência '+esc(a.carenciaLeite)+'d';if(a.carenciaCarne)carStr+=(carStr?' · ':'')+'🥩 carência '+esc(a.carenciaCarne)+'d';return`<div class="animal-row" style="animation-delay:${i*0.03}s;flex-direction:column;align-items:stretch"><div style="display:flex;justify-content:space-between;align-items:flex-start"><div class="animal-info">${a.tipo?'<div class="badges" style="margin-bottom:4px"><span class="badge badge-muco">'+esc(a.tipo)+'</span></div>':''}${medStr?'<div class="detail">'+medStr+'</div>':''}${dateStr?'<div class="detail">'+dateStr+'</div>':''}${carStr?'<div class="detail">'+carStr+'</div>':''}</div><div class="animal-actions"><button class="edit-btn" onclick="editMedDirect('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button><button class="del-btn" onclick="delMedDirect('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 6h18M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2"/></svg></button></div></div><div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:8px">${animalBadges}</div></div>`}).join('')}
function editMedDirect(aid){const a=DB.medDirect.find(x=>x.id===aid);if(!a)return;editAniId=aid;const animals=a.animais||[{num:a.num,nome:a.nome}];setMedMode('individual');tempMedAnimals=animals.map(x=>({num:x.num,nome:x.nome,included:true}));renderMedIndivList();populateMedSelect();document.getElementById('medDataIni').value=a.dataIni||'';document.getElementById('medDataFim').value=a.dataFim||'';document.getElementById('medTipo').value=a.tipo||'Vacina';document.getElementById('medCarLeite').value=a.carenciaLeite||'';document.getElementById('medCarCarne').value=a.carenciaCarne||'';if(Array.isArray(a.medicamentos)){setMedRows(a.medicamentos)}else{setMedRows([{nome:a.nomeMed||'',dose:a.dosagem||''}])}document.getElementById('medAnimalModalTitle').textContent='Editar Medicação';openModal('medAnimalModal')}
async function delMedDirect(aid){const ok=await showConfirm('Excluir?','🗑️');if(!ok)return;DB.medDirect=DB.medDirect.filter(x=>x.id!==aid);save();renderMedDirect();toast('Excluído')}

// ========== ALIMENTAÇÃO (lote + individual) ==========
let aliMode='lote';let tempAliAnimals=[];
function setAliMode(mode){aliMode=mode;document.getElementById('aliModeLote').classList.toggle('active',mode==='lote');document.getElementById('aliModeIndiv').classList.toggle('active',mode==='individual');document.getElementById('aliLoteSection').classList.toggle('hidden',mode!=='lote');document.getElementById('aliIndivSection').classList.toggle('hidden',mode!=='individual');calcAliCost()}
function populateAliLoteSelect(){const sel=document.getElementById('aliLoteSelect');sel.innerHTML='<option value="">Selecione o lote...</option>';DB.lotes.forEach(l=>{sel.innerHTML+=`<option value="${l.id}">${esc(l.name)} (${l.animals.length})</option>`})}
function populateAliAnimalSelect2(){const sel=document.getElementById('aliAnimalSelect');sel.innerHTML='<option value="">Selecione...</option>';sortByNum(getAllAnimals().slice()).forEach(a=>{sel.innerHTML+=`<option value="${esc(a.num)}|${esc(a.nome)}">#${esc(a.num)} - ${esc(a.nome)} (${esc(a.loteName)})</option>`})}
function loadAliLoteAnimals(){const lid=document.getElementById('aliLoteSelect').value;const container=document.getElementById('aliLoteAnimals');if(!lid){container.innerHTML='';calcAliCost();return}const l=DB.lotes.find(x=>x.id===lid);if(!l)return;tempAliAnimals=l.animals.map(a=>({num:a.num,nome:a.nome,included:true}));renderAliLoteList();calcAliCost()}
function renderAliLoteList(){const container=document.getElementById('aliLoteAnimals');container.innerHTML=tempAliAnimals.map((a,i)=>`<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;border-radius:6px;margin-bottom:4px;background:${a.included?'rgba(78,232,152,0.1)':'rgba(255,87,87,0.08)'}"><label style="display:flex;align-items:center;gap:6px;cursor:pointer;flex:1;font-size:.8rem;color:${a.included?'var(--g300)':'var(--danger)'}"><input type="checkbox" ${a.included?'checked':''} onchange="tempAliAnimals[${i}].included=this.checked;renderAliLoteList();calcAliCost()" style="accent-color:var(--g500)">#${a.num} ${a.nome}</label></div>`).join('')}
function addAliAnimalNew(){const sel=document.getElementById('aliAnimalSelect');if(!sel.value)return;const[num,nome]=sel.value.split('|');if(tempAliAnimals.find(a=>a.num===num))return toast('Já adicionado','info');tempAliAnimals.push({num,nome,included:true});renderTempAliAnimals();sel.selectedIndex=0;calcAliCost()}
function renderTempAliAnimals(){document.getElementById('aliSelectedAnimals').innerHTML=tempAliAnimals.map((a,i)=>`<span class="badge badge-cat" style="cursor:pointer;padding:5px 12px" onclick="tempAliAnimals.splice(${i},1);renderTempAliAnimals();calcAliCost()">#${esc(a.num)} ${esc(a.nome)} ✕</span>`).join('')}
function onDietChange2(){const checks=document.querySelectorAll('#dietaChecks input[type=checkbox]');const container=document.getElementById('dietDetailFields');container.innerHTML='';checks.forEach(cb=>{if(cb.checked){container.innerHTML+=`<div class="diet-qtd" style="flex-direction:column;gap:6px;padding:12px 14px"><div class="diet-label" style="min-width:auto;margin-bottom:4px">${cb.value}</div><div class="flex-row"><div class="form-group" style="margin-bottom:0"><label style="font-size:.65rem">Valor/kg (R$)</label><input class="form-input" id="dietVal_${cb.value}" type="number" step="0.01" placeholder="R$/kg" style="padding:9px 12px;font-size:.82rem" oninput="calcAliCost()"></div><div class="form-group" style="margin-bottom:0"><label style="font-size:.65rem">Consumo/animal (kg)</label><input class="form-input" id="dietKg_${cb.value}" type="number" step="0.1" placeholder="kg/animal" style="padding:9px 12px;font-size:.82rem" oninput="calcAliCost()"></div></div></div>`}});calcAliCost()}
function calcAliCost(){const checks=document.querySelectorAll('#dietaChecks input[type=checkbox]:checked');const numAni=tempAliAnimals.filter(a=>a.included!==false).length;let totalCost=0;const preview=document.getElementById('aliCostPreview');let lines='';checks.forEach(cb=>{const val=parseFloat(document.getElementById('dietVal_'+cb.value)?.value||0);const kg=parseFloat(document.getElementById('dietKg_'+cb.value)?.value||0);const cost=val*kg*numAni;totalCost+=cost;if(val||kg)lines+=`<div style="display:flex;justify-content:space-between;font-size:.75rem;color:var(--text2);padding:2px 0"><span>${cb.value}: ${kg}kg × ${numAni} anim. × R$${val.toFixed(2)}</span><span>R$ ${cost.toFixed(2)}</span></div>`});if(lines||numAni)preview.innerHTML=`<div class="glass3" style="border-radius:var(--rx);padding:12px;margin-top:4px"><div style="font-size:.72rem;color:var(--text3);margin-bottom:6px">${numAni} animal(is)</div>${lines}<div style="display:flex;justify-content:space-between;font-size:.9rem;font-weight:700;color:var(--g400);border-top:1px solid rgba(255,255,255,0.1);padding-top:8px;margin-top:6px"><span>Custo Total</span><span>R$ ${totalCost.toFixed(2)}</span></div></div>`;else preview.innerHTML=''}
function getSelectedDiets2(){const diets=[];document.querySelectorAll('#dietaChecks input[type=checkbox]:checked').forEach(cb=>{const valEl=document.getElementById('dietVal_'+cb.value);const kgEl=document.getElementById('dietKg_'+cb.value);diets.push({tipo:cb.value,valorKg:valEl?valEl.value:'',kg:kgEl?kgEl.value:''})});return diets}
function saveAliDirect(){const dietas=getSelectedDiets2();if(!dietas.length)return toast('Selecione ao menos um tipo de dieta','error');const animais=tempAliAnimals.filter(a=>a.included!==false).map(a=>({num:a.num,nome:a.nome,aid:a.aid||resolveAid(a.num)}));if(!animais.length)return toast('Adicione ao menos um animal','error');const nomeDieta=document.getElementById('aliNomeDieta').value.trim()||'Sem título';let totalCost=0;dietas.forEach(d=>{totalCost+=parseFloat(d.valorKg||0)*parseFloat(d.kg||0)*animais.length});const d={nomeDieta,dietas,animais,numAnimais:animais.length,custoTotal:totalCost};if(editAniId){const a=DB.aliDirect.find(x=>x.id===editAniId);if(a)Object.assign(a,d)}else DB.aliDirect.push({id:uid(),createdAt:Date.now(),...d});tempAliAnimals=[];save();closeModal('aliAnimalModal');renderAliDirect();toast('Alimentação salva!')}
function renderAliDirect(){const container=document.getElementById('aliDirectList');const costGrid=document.getElementById('aliCostGrid');const items=[...DB.aliDirect].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));let totalGeral=0;items.forEach(a=>totalGeral+=parseFloat(a.custoTotal||0));costGrid.innerHTML=items.length?`<div class="cost-box glass3"><div class="val">R$ ${totalGeral.toFixed(2)}</div><div class="lbl">Custo Total</div></div><div class="cost-box glass3"><div class="val">${items.length}</div><div class="lbl">Dietas</div></div>`:'';if(!items.length){container.innerHTML='<div class="empty-state"><p>Nenhuma alimentação registrada.</p></div>';return}container.innerHTML=items.map((a,i)=>{const dietBadges=a.dietas.map(d=>`<span class="badge badge-cat" style="margin:2px">${esc(d.tipo)}: ${d.kg||0}kg × R$${parseFloat(d.valorKg||0).toFixed(2)}</span>`).join('');const animalBadges=(a.animais||[]).map(x=>`<span class="badge badge-m" style="margin:1px">#${esc(x.num)} ${esc(x.nome)}</span>`).join('');return`<div class="animal-row" style="animation-delay:${i*0.03}s;flex-direction:column;align-items:stretch"><div style="display:flex;justify-content:space-between;align-items:center"><div><div style="font-family:'JetBrains Mono',monospace;font-weight:700;color:var(--g400);font-size:.9rem">${esc(a.nomeDieta||'Dieta')}</div><div class="detail">${a.numAnimais||0} animais · R$ ${parseFloat(a.custoTotal||0).toFixed(2)}</div></div><div class="animal-actions"><button class="edit-btn" onclick="editAliDirect('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button><button class="del-btn" onclick="delAliDirect('${a.id}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 6h18M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6m3 0V4a2 2 0 012-2h4a2 2 0 012 2v2"/></svg></button></div></div><div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:8px">${dietBadges}</div><div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px">${animalBadges}</div></div>`}).join('')}
function editAliDirect(aid){const a=DB.aliDirect.find(x=>x.id===aid);if(!a)return;editAniId=aid;document.getElementById('aliNomeDieta').value=a.nomeDieta||'';document.querySelectorAll('#dietaChecks input[type=checkbox]').forEach(cb=>cb.checked=false);a.dietas.forEach(d=>{const cb=document.querySelector('#dietaChecks input[value="'+d.tipo+'"]');if(cb)cb.checked=true});onDietChange2();a.dietas.forEach(d=>{const ve=document.getElementById('dietVal_'+d.tipo);if(ve)ve.value=d.valorKg||'';const ke=document.getElementById('dietKg_'+d.tipo);if(ke)ke.value=d.kg||''});setAliMode('individual');tempAliAnimals=(a.animais||[]).map(x=>({...x,included:true}));renderTempAliAnimals();populateAliAnimalSelect2();calcAliCost();document.getElementById('aliAnimalModalTitle').textContent='Editar Alimentação';openModal('aliAnimalModal')}
async function delAliDirect(aid){const ok=await showConfirm('Excluir?','🗑️');if(!ok)return;DB.aliDirect=DB.aliDirect.filter(x=>x.id!==aid);save();renderAliDirect();toast('Excluído')}

// ========== HOME ==========
let chartFilter='categoria';
const COLORS=['#1bd171','#5b9aff','#ffb830','#ff4757','#a78bfa','#f472b6','#2dd4bf','#fb923c','#818cf8','#a3e635','#fbbf24','#67e8f9'];
function setChartFilter(f,btn){chartFilter=f;document.querySelectorAll('.filter-chip').forEach(c=>c.classList.remove('active'));btn.classList.add('active');renderHome()}
function renderHome(){const all=getAllAnimals();const today=new Date().toISOString().split('T')[0];const hour=new Date().getHours();const greet=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';document.getElementById('statGrid').innerHTML=`<div style="grid-column:1/-1;margin-bottom:4px"><p style="font-size:1rem;font-weight:700;color:var(--brown)">${greet}, ${esc(DB.user.name||'Usuário')}!</p><p style="font-size:.75rem;color:var(--brown);margin-top:2px">${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</p></div><div class="stat-card glass2 anim-fade"><div class="stat-icon">🐄</div><div class="stat-val">${all.length}</div><div class="stat-lbl">Total Animais</div></div><div class="stat-card glass2 anim-fade anim-d1"><div class="stat-icon">📋</div><div class="stat-val">${DB.lotes.length}</div><div class="stat-lbl">Lotes</div></div>`;const counts={};const medNums=new Set();DB.medDirect.forEach(rec=>{if(!rec.dataFim||rec.dataFim>=today)(rec.animais||[{num:rec.num}]).forEach(a=>{if(a.num)medNums.add(a.num)})});const insemNums=new Set();DB.inseminacao.forEach(p=>p.animals.forEach(a=>insemNums.add(a.num)));if(chartFilter==='lote'){DB.lotes.forEach(l=>{if(l.animals.length)counts[l.name]=l.animals.length})}else if(chartFilter==='medicado'){let mc=0,nm=0;all.forEach(a=>{if(medNums.has(a.num))mc++;else nm++});if(mc)counts['Em medicação']=mc;if(nm)counts['Sem medicação']=nm}else if(chartFilter==='inseminado'){let ic=0,ni=0;all.forEach(a=>{if(insemNums.has(a.num))ic++;else ni++});if(ic)counts['Inseminado']=ic;if(ni)counts['Não inseminado']=ni}else if(chartFilter==='origem'){all.forEach(a=>{const k=a.origem||'Não informado';counts[k]=(counts[k]||0)+1})}else{all.forEach(a=>{let k='';if(chartFilter==='categoria')k=a.cat;else if(chartFilter==='sexo')k=a.sexo;else if(chartFilter==='situacao')k=a.sit;else k=a.raca||'N/A';counts[k]=(counts[k]||0)+1})}drawPie(counts);renderHomeAlerts();renderFarmPanel()}
function drawPie(data){const c=document.getElementById('pieChart'),ctx=c.getContext('2d'),W=c.width,H=c.height,cx=W/2,cy=H/2,r=Math.min(W,H)/2-16;ctx.clearRect(0,0,W,H);const keys=Object.keys(data),total=keys.reduce((s,k)=>s+data[k],0);const leg=document.getElementById('chartLegend');if(!total){ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.strokeStyle='rgba(78,232,152,0.15)';ctx.lineWidth=20;ctx.stroke();ctx.fillStyle='rgba(195,249,221,0.3)';ctx.font='500 13px Sora';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('Sem dados',cx,cy);leg.innerHTML='';return}let start=-Math.PI/2;leg.innerHTML='';keys.forEach((k,i)=>{const angle=(data[k]/total)*Math.PI*2;const color=COLORS[i%COLORS.length];ctx.beginPath();ctx.arc(cx,cy,r,start,start+angle);ctx.arc(cx,cy,r*0.55,start+angle,start,true);ctx.closePath();ctx.fillStyle=color;ctx.fill();if(angle>0.35){const mid=start+angle/2;const lx=cx+Math.cos(mid)*(r*0.78);const ly=cy+Math.sin(mid)*(r*0.78);ctx.fillStyle='#fff';ctx.font='700 11px Sora';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(data[k],lx,ly)}start+=angle;leg.innerHTML+=`<div class="legend-item"><div class="legend-dot" style="background:${color}"></div>${esc(k)} (${data[k]})</div>`});ctx.fillStyle='#fff';ctx.font='700 22px JetBrains Mono';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(total,cx,cy-6);ctx.fillStyle='rgba(195,249,221,0.5)';ctx.font='500 10px Sora';ctx.fillText('TOTAL',cx,cy+12)}

// ========== RELATÓRIOS ==========
function populateReportSources(){const container=document.getElementById('reportSourceChecks');container.innerHTML='';DB.lotes.forEach(l=>{container.innerHTML+=`<label class="report-check"><input type="checkbox" value="lote:${l.id}"><span>Rebanho — ${esc(l.name)} (${l.animals.length})</span></label>`});if(DB.medDirect.length)container.innerHTML+=`<label class="report-check"><input type="checkbox" value="medicacao"><span>Medicação (${DB.medDirect.length})</span></label>`;if(DB.aliDirect.length)container.innerHTML+=`<label class="report-check"><input type="checkbox" value="alimentacao"><span>Alimentação (${DB.aliDirect.length})</span></label>`;DB.inseminacao.forEach(p=>{container.innerHTML+=`<label class="report-check"><input type="checkbox" value="inseminacao:${p.id}"><span>Insem. — ${esc(p.name)} (${p.animals.length})</span></label>`})}
function getFiltered(){const checks=document.querySelectorAll('#reportSourceChecks input[type=checkbox]:checked');if(!checks.length)return{animals:[]};let allAnimals=[];const cf=document.getElementById('reportFilterCat').value;const sf=document.getElementById('reportFilterSex').value;const stf=document.getElementById('reportFilterSit').value;const insemF=document.getElementById('reportFilterInsem').value;const insemNums=new Set();DB.inseminacao.forEach(p=>p.animals.forEach(a=>insemNums.add(a.num)));checks.forEach(cb=>{const val=cb.value;if(val.startsWith('lote:')){const id=val.split(':')[1];const l=DB.lotes.find(x=>x.id===id);if(l){let items=l.animals.map(a=>({...a,loteName:l.name}));if(cf)items=items.filter(a=>a.cat===cf);if(sf)items=items.filter(a=>a.sexo===sf);if(stf)items=items.filter(a=>a.sit===stf);if(insemF==='sim')items=items.filter(a=>insemNums.has(a.num));else if(insemF==='nao')items=items.filter(a=>!insemNums.has(a.num));items.forEach(a=>allAnimals.push({...a,_type:'rebanho',_planilha:'Rebanho — '+l.name}))}}else if(val==='medicacao'){DB.medDirect.forEach(a=>allAnimals.push({...a,_type:'medicacao',_planilha:'Medicação'}))}else if(val==='alimentacao'){DB.aliDirect.forEach(a=>allAnimals.push({...a,_type:'alimentacao',_planilha:'Alimentação'}))}else if(val.startsWith('inseminacao:')){const id=val.split(':')[1];const p=DB.inseminacao.find(x=>x.id===id);if(p)p.animals.forEach(a=>allAnimals.push({...a,_type:'inseminacao',_planilha:'Insem. — '+p.name}))}});return{animals:allAnimals}}
function getReportFields(){const fields=[];document.querySelectorAll('#reportFieldChecks input[type=checkbox]:checked').forEach(cb=>fields.push(cb.value));return fields}
function csvEscape(v){const s=String(v==null?'':v);return s.includes(',')||s.includes('"')||s.includes('\n')?'"'+s.replace(/"/g,'""')+'"':s}
function downloadReport(fmt){const result=getFiltered();if(!result.animals.length)return toast('Selecione fontes e verifique filtros','error');const animals=result.animals;const now=new Date(),ds=now.toLocaleDateString('pt-BR'),ts=now.toLocaleTimeString('pt-BR');const grouped={};animals.forEach(a=>{const key=a._type+'|'+a._planilha;if(!grouped[key])grouped[key]={type:a._type,planilha:a._planilha,items:[]};grouped[key].items.push(a)});const fields=getReportFields();const fieldMap={num:'Nº',nome:'Nome',sexo:'Sexo',cat:'Cat.',sit:'Sit.',raca:'Raça',peso:'Peso',leite:'Leite',idade:'Idade',origem:'Origem',tipoPrenhez:'Tipo Prenhez',pais:'Mãe/Pai',pesagem:'Pesagens',ultimoParto:'Últ. Parto',prenha:'Dias Prenha',insem:'Últ. Insem.',lote:'Lote'};if(fmt==='csv'){let csv='';Object.values(grouped).forEach(g=>{csv+=`\n--- ${g.planilha} ---\n`;if(g.type==='rebanho'){csv+=fields.map(f=>fieldMap[f]||f).join(',')+'\n';csv+=g.items.map(a=>{return fields.map(f=>{if(f==='num')return a.num;if(f==='nome')return a.nome;if(f==='sexo')return a.sexo;if(f==='cat')return a.cat;if(f==='sit')return a.sit;if(f==='raca')return a.raca;if(f==='peso')return a.peso||'';if(f==='leite')return a.leite||'';if(f==='idade')return ageMonths(a.dataNasc)||'';if(f==='origem')return a.origem||'';if(f==='tipoPrenhez')return a.tipoPrenhez||'';if(f==='pais')return(a.nomeMae||'')+'/'+(a.nomePai||'');if(f==='pesagem')return(a.pesagens||[]).map(p=>p.peso+'kg('+p.data+')').join('; ');if(f==='ultimoParto')return a.ultimoParto?new Date(a.ultimoParto+'T12:00').toLocaleDateString('pt-BR'):'';if(f==='prenha')return a.prenhaData?ageDays(a.prenhaData)+' dias':'';if(f==='insem')return getInsemDate(a.num)||'';if(f==='lote')return a.loteName||'';return''}).map(csvEscape).join(',')}).join('\n')}else if(g.type==='inseminacao'){csv+='Numero,Nome,Data,Tempo,Touro,Muco,Obs\n';csv+=g.items.map(a=>[a.num,a.nome,a.data||'',a.tempo||'',a.touro||'',a.muco||'',a.obs||''].map(csvEscape).join(',')).join('\n');}else if(g.type==='medicacao'){csv+='Numero,Nome,Tipo,Medicamentos,Inicio,Fim\n';g.items.forEach(a=>{const animals=a.animais||[{num:a.num||'',nome:a.nome||''}];const meds=Array.isArray(a.medicamentos)?a.medicamentos.map(m=>m.nome+(m.dose?' ('+m.dose+')':'')).join('; '):(a.nomeMed||'')+(a.dosagem?' ('+a.dosagem+')':'');animals.forEach(an=>{csv+=[an.num,an.nome,a.tipo||'',meds,a.dataIni||'',a.dataFim||''].map(csvEscape).join(',')+'\n'})});}else if(g.type==='alimentacao'){csv+='Dietas,Animais,Qtd,Custo\n';let aliT=0;csv+=g.items.map(a=>{const dt=(a.dietas||[]).map(d=>`${d.tipo}:${d.kg||0}kg@R$${parseFloat(d.valorKg||0).toFixed(2)}`).join('; ');aliT+=parseFloat(a.custoTotal||0);return`"${dt}","${(a.animais||[]).map(x=>x.num+'-'+x.nome).join('; ')}",${a.numAnimais||0},${parseFloat(a.custoTotal||0).toFixed(2)}`}).join('\n');csv+=`\nTOTAL,,, R$ ${aliT.toFixed(2)}`}csv+='\n'});const b=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'});const l=document.createElement('a');l.href=URL.createObjectURL(b);l.download=`ELTECH_${ds.replace(/\//g,'-')}.csv`;l.click();setTimeout(()=>URL.revokeObjectURL(l.href),1000);toast('Excel baixado!')}else{let tables='';Object.values(grouped).forEach(g=>{let rows='';if(g.type==='rebanho'){rows='<tr class="hdr">'+fields.map(f=>`<th>${fieldMap[f]||f}</th>`).join('')+'</tr>';rows+=g.items.map((a,i)=>{return`<tr class="${i%2?'alt':''}">` +fields.map(f=>{if(f==='num')return`<td>${a.num}</td>`;if(f==='nome')return`<td>${a.nome}</td>`;if(f==='sexo')return`<td>${a.sexo}</td>`;if(f==='cat')return`<td>${a.cat}</td>`;if(f==='sit')return`<td>${a.sit}</td>`;if(f==='raca')return`<td>${a.raca||'—'}</td>`;if(f==='peso')return`<td>${a.peso?a.peso+'kg':'—'}</td>`;if(f==='leite')return`<td>${a.leite?a.leite+'L':'—'}</td>`;if(f==='idade')return`<td>${ageMonths(a.dataNasc)||'—'} m</td>`;if(f==='origem')return`<td>${a.origem||'—'}</td>`;if(f==='tipoPrenhez')return`<td>${a.tipoPrenhez||'—'}</td>`;if(f==='pais')return`<td>${a.nomeMae||'—'} / ${a.nomePai||'—'}</td>`;if(f==='pesagem')return`<td style="font-size:10px">${(a.pesagens||[]).map(p=>p.peso+'kg').join(', ')||'—'}</td>`;if(f==='ultimoParto')return`<td>${a.ultimoParto?new Date(a.ultimoParto+'T12:00').toLocaleDateString('pt-BR'):'—'}</td>`;if(f==='prenha')return`<td>${a.prenhaData?ageDays(a.prenhaData)+' dias':'—'}</td>`;if(f==='insem')return`<td>${getInsemDate(a.num)||'—'}</td>`;if(f==='lote')return`<td>${a.loteName||'—'}</td>`;return'<td>—</td>'}).join('')+'</tr>'}).join('')}else if(g.type==='inseminacao')rows='<tr class="hdr"><th>Nº</th><th>Nome</th><th>Data</th><th>Tempo</th><th>Touro</th><th>Muco</th><th>Obs</th></tr>'+g.items.map((a,i)=>`<tr class="${i%2?'alt':''}"><td>${a.num}</td><td>${a.nome}</td><td>${a.data}</td><td>${a.tempo}</td><td>${a.touro}</td><td>${a.muco}</td><td>${a.obs||''}</td></tr>`).join('');else if(g.type==='medicacao'){rows='<tr class="hdr"><th>Animais</th><th>Tipo</th><th>Medicamentos</th><th>Início</th><th>Fim</th></tr>';rows+=g.items.map((a,i)=>{const animals=a.animais||[{num:a.num||'',nome:a.nome||''}];const anStr=animals.map(x=>'#'+x.num+' '+x.nome).join(', ');const meds=Array.isArray(a.medicamentos)?a.medicamentos.map(m=>m.nome+(m.dose?' ('+m.dose+')':'')).join(', '):(a.nomeMed||'—')+(a.dosagem?' ('+a.dosagem+')':'');return`<tr class="${i%2?'alt':''}"><td>${anStr}</td><td>${a.tipo||'—'}</td><td>${meds}</td><td>${a.dataIni||'—'}</td><td>${a.dataFim||'—'}</td></tr>`}).join('');}else if(g.type==='alimentacao'){let aliT=0;rows='<tr class="hdr"><th>Dietas</th><th>Animais</th><th>Qtd</th><th>Custo</th></tr>'+g.items.map((a,i)=>{const dt=(a.dietas||[]).map(d=>`${d.tipo}: ${d.kg||0}kg/an × R$${parseFloat(d.valorKg||0).toFixed(2)}`).join('<br>');aliT+=parseFloat(a.custoTotal||0);return`<tr class="${i%2?'alt':''}"><td>${dt}</td><td style="font-size:10px">${(a.animais||[]).map(x=>'#'+x.num).join(', ')}</td><td>${a.numAnimais||0}</td><td><strong>R$ ${parseFloat(a.custoTotal||0).toFixed(2)}</strong></td></tr>`}).join('');rows+=`<tr style="background:#86693f;color:#fff;font-weight:700"><td colspan="3" style="text-align:right;border:none;padding:12px">TOTAL</td><td style="border:none;padding:12px">R$ ${aliT.toFixed(2)}</td></tr>`}tables+=`<h2 style="color:#86693f;font-size:16px;margin:24px 0 8px;border-bottom:2px solid #86693f;padding-bottom:6px">${g.planilha}</h2><table>${rows}</table><p style="font-size:11px;color:#999;margin-top:4px">${g.items.length} registro(s)</p>`});const html=`<!DOCTYPE html><html><head><meta charset="utf-8"><title>ELTECH</title><style>*{margin:0;box-sizing:border-box}body{font-family:Segoe UI,sans-serif;padding:40px 24px;color:#1a1a1a;background:#fff}.hd{text-align:center;margin-bottom:24px}.hd h1{color:#86693f;font-size:28px;letter-spacing:3px}.hd p{color:#666;font-size:12px}table{width:100%;border-collapse:collapse;font-size:12px;margin-bottom:4px}th,td{padding:9px 10px;text-align:left;border-bottom:1px solid #e5e5e5}.hdr th{background:linear-gradient(135deg,#86693f,#a98e5f);color:#fff;font-weight:600;border:none;font-size:11px}.alt td{background:#f0fdf4}.ft{text-align:center;margin-top:30px;padding-top:14px;border-top:2px solid #86693f;color:#666;font-size:11px}</style></head><body><div class="hd"><h1>ELTECH</h1><p>Relatório · ${ds} às ${ts}</p></div>${tables}<div class="ft">Total: ${animals.length} registro(s) · Gerado por ELTECH</div></body></html>`;const blob=new Blob([html],{type:'text/html'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ELTECH_${ds.replace(/\//g,'-')}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Relatório baixado!')}}

// ========== CONFIG ==========
function setAvatar(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=ev=>{DB.user.avatar=ev.target.result;document.getElementById('avatarImg').src=ev.target.result;document.getElementById('avatarImg').style.display='block';document.getElementById('avatarPlaceholder').style.display='none';save();toast('Foto atualizada!')};r.readAsDataURL(f)}
document.getElementById('profileName').addEventListener('change',function(){DB.user.name=this.value;save();toast('Nome salvo!')});
async function changePassword(){const o=document.getElementById('cfgOldPass').value;const n=document.getElementById('cfgNewPass').value;if(!o||!n)return toast('Preencha os campos','error');const stored=DB.user.password;const oldOk=isHash(stored)?(await hashPass(o))===stored:o===stored;if(!oldOk)return toast('Senha atual incorreta','error');if(!isValidPassword(n))return toast('Nova senha precisa de: maiúscula, número e caractere especial','error');DB.user.password=await hashPass(n);save();toast('Senha alterada!');document.getElementById('cfgOldPass').value='';document.getElementById('cfgNewPass').value=''}

// ========== BACKUP ==========
function exportBackup(){const data=JSON.stringify(DB,null,2);const blob=new Blob([data],{type:'application/json'});const a=document.createElement('a');const d=new Date();a.href=URL.createObjectURL(blob);a.download=`ELTECH_backup_${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);if(!DB.meta)DB.meta={lastBackup:0,changes:0};DB.meta.lastBackup=Date.now();DB.meta.changes=0;upsertActive();persistAccounts();const bb=document.getElementById('backupBanner');if(bb)bb.remove();toast('Backup exportado!')}
function importBackup(e){const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=async function(ev){try{const data=JSON.parse(ev.target.result);const ok=await showConfirm('Substituir os dados DESTA conta?','📦');if(!ok)return;data.id=DB.id;DB=data;normalizeAccount(DB);save();if(DB.user.name)document.getElementById('profileName').value=DB.user.name;if(DB.user.avatar){document.getElementById('avatarImg').src=DB.user.avatar;document.getElementById('avatarImg').style.display='block';document.getElementById('avatarPlaceholder').style.display='none'}goPage('pageHome');toast('Backup restaurado!')}catch(err){toast('Arquivo inválido','error')}};reader.readAsText(file);e.target.value=''}

// ========== LEMBRETE DE BACKUP ==========
function checkBackupReminder(){if(!DB.meta)return;const changes=DB.meta.changes||0;if(changes>=30)showBackupBanner(changes)}
function showBackupBanner(changes){if(document.getElementById('backupBanner'))return;const d=document.createElement('div');d.id='backupBanner';d.style.cssText='position:fixed;bottom:80px;left:16px;right:16px;z-index:65;padding:16px 20px;border-radius:16px;display:flex;align-items:center;justify-content:space-between;gap:12px;animation:slideUp .4s ease';d.className='glass';d.innerHTML=`<div style="flex:1"><div style="font-weight:700;font-size:.88rem">💾 Faça um backup</div><div style="font-size:.72rem;color:var(--text2);margin-top:2px">${changes} alteração(ões) desde o último backup</div></div><button class="btn btn-primary btn-sm" onclick="exportBackup()" style="flex-shrink:0">Baixar</button><button onclick="this.parentElement.remove()" style="background:none;border:none;color:var(--text3);cursor:pointer;padding:4px;font-size:1.2rem">✕</button>`;document.body.appendChild(d)}

// ========== ALERTAS (medicação, carência, reprodução) ==========
const GESTACAO_DIAS=283;
function getAlerts(){const alerts=[];const today=new Date();today.setHours(0,0,0,0);const todayTs=today.getTime();const fmt=d=>d.toLocaleDateString('pt-BR');const addDays=(s,n)=>{const d=new Date(s+'T12:00');d.setDate(d.getDate()+n);return d};const dleft=d=>Math.round((d.getTime()-todayTs)/86400000);
  // Medicação em andamento + carência de leite/carne
  DB.medDirect.forEach(rec=>{const animais=rec.animais||[{num:rec.num,nome:rec.nome}];const nomes=animais.map(a=>'#'+esc(a.num)).join(', ');const base=rec.dataFim||rec.dataIni;
    if(rec.dataIni){const ini=new Date(rec.dataIni+'T12:00').getTime();const fim=rec.dataFim?new Date(rec.dataFim+'T12:00').getTime():null;if(todayTs>=ini&&(fim===null||todayTs<=fim))alerts.push({icon:'💊',color:'var(--info)',title:esc(rec.tipo||'Medicação')+' em andamento',detail:nomes+(rec.dataFim?' · até '+fmt(new Date(rec.dataFim+'T12:00')):'')});}
    if(base&&rec.carenciaLeite){const end=addDays(base,parseInt(rec.carenciaLeite,10)||0);const dd=dleft(end);if(dd>=0)alerts.push({icon:'🥛',color:'var(--danger)',title:'NÃO vender leite',detail:nomes+' · liberado '+fmt(end)+(dd===0?' (hoje)':' (faltam '+dd+'d)')});}
    if(base&&rec.carenciaCarne){const end=addDays(base,parseInt(rec.carenciaCarne,10)||0);const dd=dleft(end);if(dd>=0)alerts.push({icon:'🥩',color:'var(--danger)',title:'NÃO abater (carne)',detail:nomes+' · liberado '+fmt(end)+(dd===0?' (hoje)':' (faltam '+dd+'d)')});}
  });
  // Reprodução: parto previsto + diagnóstico de prenhez
  const lastInsem={};DB.inseminacao.forEach(p=>p.animals.forEach(a=>{if(a.data&&(!lastInsem[a.num]||a.data>lastInsem[a.num].data))lastInsem[a.num]={data:a.data,nome:a.nome}}));
  const byNum={};getAllAnimals().forEach(a=>{byNum[a.num]=a});
  getAllAnimals().forEach(a=>{if(a.sit==='Prenha'){const base=a.prenhaData||(lastInsem[a.num]&&lastInsem[a.num].data);if(base){const exp=addDays(base,GESTACAO_DIAS);const dd=dleft(exp);if(dd<=15&&dd>=-20)alerts.push({icon:'🐄',color:'var(--warn)',title:dd<0?'Parto pode ter passado':'Parto próximo',detail:'#'+esc(a.num)+' '+esc(a.nome)+' · '+fmt(exp)+(dd>=0?' (em '+dd+'d)':' ('+(-dd)+'d atrás)')});}}});
  Object.keys(lastInsem).forEach(num=>{const a=byNum[num];const since=Math.round((todayTs-new Date(lastInsem[num].data+'T12:00').getTime())/86400000);if(since>=28&&since<=60&&(!a||a.sit!=='Prenha'))alerts.push({icon:'🔬',color:'var(--accent2)',title:'Diagnóstico de prenhez',detail:'#'+esc(num)+' '+esc(lastInsem[num].nome)+' · inseminada há '+since+'d'});});
  return alerts;
}
function renderHomeAlerts(){const c=document.getElementById('homeAlerts');if(!c)return;const alerts=getAlerts();if(!alerts.length){c.innerHTML='';return}c.innerHTML=`<div class="chart-container glass" style="margin-bottom:16px;padding:16px 18px"><div class="med-section-title"><span class="icon">🔔</span>Alertas (${alerts.length})</div>`+alerts.map(al=>`<div class="med-alert-card glass3" style="border-left-color:${al.color}"><div class="med-animal">${al.icon} ${esc(al.title)}</div><div class="med-detail">${al.detail}</div></div>`).join('')+`</div>`}

// ========== HISTÓRICO (leite / peso) ==========
function openHist(aid){let a=null;DB.lotes.forEach(l=>{const f=l.animals.find(x=>x.id===aid);if(f)a=f});if(!a)return;document.getElementById('histModalTitle').textContent='#'+a.num+' '+a.nome;const lh=(a.leiteHist||[]).slice();const ph=(a.pesagens||[]).slice();const fmtd=s=>new Date(s+'T12:00').toLocaleDateString('pt-BR');let html='';html+=`<div class="med-section-title" style="font-size:1rem;margin-top:4px"><span class="icon" style="background:rgba(27,209,113,0.15)">🥛</span>Produção de leite (L/dia)</div>`;if(lh.length){html+=`<canvas id="leiteChart" width="300" height="150" style="width:100%;margin-bottom:6px"></canvas><div class="card-sub" style="margin-bottom:18px">${lh.map(x=>esc(x.leite)+'L · '+fmtd(x.data)).join('<br>')}</div>`}else{html+=`<div class="empty-state" style="padding:18px"><p>Sem histórico ainda.<br>Edite o animal alterando o campo "Leite" para registrar.</p></div>`}html+=`<div class="med-section-title" style="font-size:1rem"><span class="icon" style="background:rgba(91,154,255,0.15)">⚖️</span>Peso (kg)</div>`;if(ph.length){html+=`<canvas id="pesoChart" width="300" height="150" style="width:100%;margin-bottom:6px"></canvas><div class="card-sub">${ph.map(x=>esc(x.peso)+'kg · '+fmtd(x.data)).join('<br>')}</div>`}else{html+=`<div class="empty-state" style="padding:18px"><p>Sem histórico de peso ainda.</p></div>`}document.getElementById('histContent').innerHTML=html;openModal('histModal');if(lh.length)drawLineChart('leiteChart',lh.map(x=>parseFloat(x.leite)||0),'#1bd171');if(ph.length)drawLineChart('pesoChart',ph.map(x=>parseFloat(x.peso)||0),'#5b9aff')}
function drawLineChart(id,vals,color){const c=document.getElementById(id);if(!c)return;const ctx=c.getContext('2d'),W=c.width,H=c.height,pad=26;ctx.clearRect(0,0,W,H);if(!vals.length)return;const max=Math.max(...vals),min=Math.min(...vals),range=(max-min)||1,n=vals.length;const px=i=>n>1?pad+i*((W-pad*2)/(n-1)):W/2;const py=v=>H-pad-((v-min)/range)*(H-pad*2);ctx.strokeStyle='rgba(255,255,255,0.12)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad,H-pad);ctx.lineTo(W-pad,H-pad);ctx.stroke();ctx.strokeStyle=color;ctx.lineWidth=2.5;ctx.beginPath();vals.forEach((v,i)=>{const x=px(i),y=py(v);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)});ctx.stroke();ctx.font='600 10px Sora';ctx.textAlign='center';ctx.textBaseline='bottom';vals.forEach((v,i)=>{const x=px(i),y=py(v);ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.fillText(v,x,y-6)})}

// ========== VÍNCULO POR ID + FICHA DO ANIMAL ==========
// Resolve o id interno de um animal a partir do número (carimba os registros).
function resolveAid(num){const a=getAllAnimals().find(x=>String(x.num)===String(num));return a?a.id:''}
// Casa um registro (insem/med/ali) a um animal: por id se houver, senão pelo número.
function matchAnimal(entryNum,entryAid,animal){return (entryAid&&entryAid===animal.id)||String(entryNum)===String(animal.num)}
// Busca o animal completo (com lote) pelo id interno.
function getAnimalById(aid){let r=null;DB.lotes.forEach(l=>{const f=l.animals.find(x=>x.id===aid);if(f)r={...f,loteName:l.name,loteId:l.id}});return r}

function openFicha(aid){
  const a=getAnimalById(aid);if(!a)return;
  const all=getAllAnimals();
  const fmt=s=>s?new Date(s+'T12:00').toLocaleDateString('pt-BR'):'—';
  // Família
  const mae=a.nomeMae?all.find(x=>x.nome===a.nomeMae&&x.sexo==='Fêmea'):null;
  const pai=a.nomePai?all.find(x=>x.nome===a.nomePai):null;
  const filhos=all.filter(x=>x.id!==a.id&&a.nome&&(x.nomeMae===a.nome||x.nomePai===a.nome));
  // Inseminações
  const insem=[];DB.inseminacao.forEach(p=>p.animals.forEach(x=>{if(matchAnimal(x.num,x.aid,a))insem.push({plan:p.name,...x})}));
  insem.sort((m,n)=>(n.data||'').localeCompare(m.data||''));
  // Medicações
  const meds=DB.medDirect.filter(r=>(r.animais||[{num:r.num,nome:r.nome}]).some(x=>matchAnimal(x.num,x.aid,a)));
  // Alimentação + custo acumulado
  const alis=DB.aliDirect.filter(r=>(r.animais||[]).some(x=>matchAnimal(x.num,x.aid,a)));
  let feedCost=0;alis.forEach(r=>{const n=r.numAnimais||(r.animais||[]).length||1;feedCost+=parseFloat(r.custoTotal||0)/n});
  const link=(an,txt)=>`<span style="color:var(--g400);cursor:pointer;text-decoration:underline" onclick="openFicha('${an.id}')">${esc(txt)}</span>`;

  let html=`<div id="fichaPhoto" class="ficha-photo">🐄</div><div class="badges" style="margin-bottom:12px"><span class="badge ${a.sexo==='Macho'?'badge-m':'badge-f'}">${esc(a.sexo)}</span><span class="badge badge-cat">${esc(a.cat)}</span><span class="badge badge-sit">${esc(a.sit)}</span>${a.origem?`<span class="badge badge-muco">${esc(a.origem)}</span>`:''}</div>`;
  html+=`<div class="card glass2" style="margin-bottom:14px"><div class="card-sub">${ageMonths(a.dataNasc)?ageMonths(a.dataNasc)+' meses · ':''}Lote: ${esc(a.loteName||'—')}${a.raca?' · '+esc(a.raca):''}${a.peso?' · '+esc(a.peso)+'kg':''}${a.leite?' · '+esc(a.leite)+'L/dia':''}${a.dataNasc?' · Nasc.: '+fmt(a.dataNasc):''}</div></div>`;

  // Família
  html+=`<div class="med-section-title" style="font-size:1rem"><span class="icon">🧬</span>Família</div><div class="card glass3" style="margin-bottom:14px">`;
  html+=`<div class="card-sub">Mãe: ${mae?link(mae,a.nomeMae):esc(a.nomeMae||'—')}</div>`;
  html+=`<div class="card-sub" style="margin-top:4px">Pai: ${pai?link(pai,a.nomePai):esc(a.nomePai||'—')}</div>`;
  html+=`<div class="card-sub" style="margin-top:8px">Filhos (${filhos.length}):</div>`;
  html+=filhos.length?`<div class="badges" style="margin-top:4px">`+filhos.map(f=>`<span class="badge badge-cat" style="cursor:pointer" onclick="openFicha('${f.id}')">#${esc(f.num)} ${esc(f.nome)}</span>`).join('')+`</div>`:`<div class="card-sub">—</div>`;
  html+=`</div>`;

  // Reprodução
  html+=`<div class="med-section-title" style="font-size:1rem"><span class="icon" style="background:rgba(255,184,48,0.15)">🐄</span>Reprodução</div><div class="card glass3" style="margin-bottom:14px">`;
  if(a.sit==='Prenha'){const base=a.prenhaData||(insem[0]&&insem[0].data);if(base){const exp=new Date(base+'T12:00');exp.setDate(exp.getDate()+GESTACAO_DIAS);html+=`<div class="card-sub">Parto previsto: <strong style="color:var(--g300)">${exp.toLocaleDateString('pt-BR')}</strong></div>`}}
  if(a.ultimoParto)html+=`<div class="card-sub">Último parto: ${fmt(a.ultimoParto)}</div>`;
  html+=`<div class="card-sub">Inseminações: ${insem.length}</div>`;
  if(insem.length)html+=insem.map(x=>`<div class="card-sub" style="margin-top:5px">• ${fmt(x.data)}${x.touro?' · Touro: '+esc(x.touro):''}${x.tempo?' · '+esc(x.tempo):''}${x.muco?' · Muco: '+esc(x.muco):''}</div>`).join('');
  html+=`</div>`;

  // Medicações
  html+=`<div class="med-section-title" style="font-size:1rem"><span class="icon" style="background:rgba(255,87,87,0.12)">💊</span>Medicações (${meds.length})</div><div class="card glass3" style="margin-bottom:14px">`;
  html+=meds.length?meds.map(r=>{const ms=Array.isArray(r.medicamentos)?r.medicamentos.map(m=>esc(m.nome)+(m.dose?' ('+esc(m.dose)+')':'')).join(', '):esc(r.nomeMed||'');let c='';if(r.carenciaLeite)c+=' · 🥛'+esc(r.carenciaLeite)+'d';if(r.carenciaCarne)c+=' · 🥩'+esc(r.carenciaCarne)+'d';return`<div class="card-sub" style="margin-bottom:5px">• <strong>${esc(r.tipo||'')}</strong>: ${ms} ${r.dataIni?'('+fmt(r.dataIni)+(r.dataFim?'→'+fmt(r.dataFim):'')+')':''}${c}</div>`}).join(''):`<div class="card-sub">Nenhuma.</div>`;
  html+=`</div>`;

  // Alimentação + custo x retorno
  html+=`<div class="med-section-title" style="font-size:1rem"><span class="icon" style="background:rgba(78,232,152,0.12)">🌾</span>Alimentação & Custo</div><div class="card glass3" style="margin-bottom:14px"><div class="card-sub">Custo de ração acumulado: <strong style="color:var(--g400)">R$ ${feedCost.toFixed(2)}</strong></div><div class="card-sub" style="margin-top:4px">Produção atual: ${a.leite?esc(a.leite)+' L/dia':'—'}</div></div>`;

  // Evolução (gráficos)
  const lh=a.leiteHist||[],ph=a.pesagens||[];
  if(lh.length||ph.length){html+=`<div class="med-section-title" style="font-size:1rem"><span class="icon" style="background:rgba(27,209,113,0.15)">📈</span>Evolução</div>`;if(lh.length)html+=`<div class="card-sub">Leite (L/dia)</div><canvas id="fichaLeite" width="300" height="130" style="width:100%;margin-bottom:10px"></canvas>`;if(ph.length)html+=`<div class="card-sub">Peso (kg)</div><canvas id="fichaPeso" width="300" height="130" style="width:100%;margin-bottom:10px"></canvas>`;}

  // Linha do tempo
  let ev=[];
  if(a.dataNasc)ev.push({d:a.dataNasc,t:'🐣 Nascimento'});
  if(a.ultimoParto)ev.push({d:a.ultimoParto,t:'🐄 Parto'});
  insem.forEach(x=>{if(x.data)ev.push({d:x.data,t:'🔬 Inseminação'+(x.touro?' ('+esc(x.touro)+')':'')})});
  ph.forEach(x=>{if(x.data)ev.push({d:x.data,t:'⚖️ Pesagem: '+esc(x.peso)+'kg'})});
  lh.forEach(x=>{if(x.data)ev.push({d:x.data,t:'🥛 Leite: '+esc(x.leite)+'L'})});
  meds.forEach(r=>{if(r.dataIni)ev.push({d:r.dataIni,t:'💊 '+esc(r.tipo||'Medicação')})});
  ev=ev.filter(e=>e.d).sort((m,n)=>n.d.localeCompare(m.d));
  html+=`<div class="med-section-title" style="font-size:1rem"><span class="icon" style="background:rgba(91,154,255,0.12)">🕒</span>Linha do tempo</div><div class="card glass3" style="margin-bottom:8px">`+(ev.length?ev.map(e=>`<div class="card-sub" style="margin-bottom:5px">${fmt(e.d)} — ${e.t}</div>`).join(''):'<div class="card-sub">Sem eventos.</div>')+`</div>`;

  document.getElementById('fichaTitle').textContent='#'+a.num+' '+a.nome;
  document.getElementById('fichaContent').innerHTML=html;
  openModal('fichaModal');
  photoGet(a.id).then(d=>{const el=document.getElementById('fichaPhoto');if(el&&d){el.textContent='';el.style.backgroundImage=`url('${d}')`}});
  if(lh.length)drawLineChart('fichaLeite',lh.map(x=>parseFloat(x.leite)||0),'#1bd171');
  if(ph.length)drawLineChart('fichaPeso',ph.map(x=>parseFloat(x.peso)||0),'#5b9aff');
}

// ========== PAINEL DO SÍTIO ==========
function renderFarmPanel(){
  const c=document.getElementById('farmPanel');if(!c)return;
  const all=getAllAnimals();
  const lact=all.filter(a=>a.cat==='Vaca em lactação');
  const leiteTotal=lact.reduce((s,a)=>s+(parseFloat(a.leite)||0),0);
  const femAptas=all.filter(a=>a.sexo==='Fêmea'&&a.cat!=='Bezerra');
  const prenhas=femAptas.filter(a=>a.sit==='Prenha').length;
  const taxa=femAptas.length?Math.round(prenhas/femAptas.length*100):0;
  const custoAli=DB.aliDirect.reduce((s,r)=>s+parseFloat(r.custoTotal||0),0);
  const t=new Date();t.setHours(0,0,0,0);const ts=t.getTime();
  const emTrat=DB.medDirect.filter(r=>{if(!r.dataIni)return false;const ini=new Date(r.dataIni+'T12:00').getTime();const fim=r.dataFim?new Date(r.dataFim+'T12:00').getTime():null;return ts>=ini&&(fim===null||ts<=fim)}).length;
  if(!all.length){c.innerHTML='';return}
  const box=(val,lbl)=>`<div class="cost-box glass3"><div class="val">${val}</div><div class="lbl">${lbl}</div></div>`;
  c.innerHTML=`<div class="chart-container glass" style="margin-bottom:16px;padding:16px 18px"><div class="med-section-title">Painel do Sítio</div><div class="cost-grid">`+box(leiteTotal.toFixed(0)+'L','Leite/dia')+box(lact.length,'Em lactação')+box(taxa+'%','Taxa prenhez')+box(prenhas,'Prenhas')+box('R$ '+custoAli.toFixed(0),'Custo ração')+box(emTrat,'Em tratamento')+`</div></div>`;
}

// ========== FOTOS DOS ANIMAIS (IndexedDB) ==========
const PHOTO_DB='eltech_photos',PHOTO_STORE='photos';let _pdb=null;
function photoDB(){return new Promise((resolve,reject)=>{if(_pdb)return resolve(_pdb);if(!('indexedDB' in window))return reject('sem indexedDB');const r=indexedDB.open(PHOTO_DB,1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains(PHOTO_STORE))db.createObjectStore(PHOTO_STORE)};r.onsuccess=()=>{_pdb=r.result;resolve(_pdb)};r.onerror=()=>reject(r.error)})}
function photoPut(aid,dataURL){return photoDB().then(db=>new Promise((res,rej)=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).put(dataURL,aid);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})).catch(()=>{})}
function photoGet(aid){return photoDB().then(db=>new Promise(res=>{const tx=db.transaction(PHOTO_STORE,'readonly');const rq=tx.objectStore(PHOTO_STORE).get(aid);rq.onsuccess=()=>res(rq.result||null);rq.onerror=()=>res(null)})).catch(()=>null)}
function photoDel(aid){return photoDB().then(db=>new Promise(res=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).delete(aid);tx.oncomplete=()=>res();tx.onerror=()=>res()})).catch(()=>{})}
function photoAll(){return photoDB().then(db=>new Promise(res=>{const out={};const tx=db.transaction(PHOTO_STORE,'readonly');const cur=tx.objectStore(PHOTO_STORE).openCursor();cur.onsuccess=e=>{const c=e.target.result;if(c){out[c.key]=c.value;c.continue()}else res(out)};cur.onerror=()=>res(out)})).catch(()=>({}))}
function compressImage(file,maxSize,quality){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=e=>{const img=new Image();img.onload=()=>{let w=img.width,h=img.height;if(w>h){if(w>maxSize){h=Math.round(h*maxSize/w);w=maxSize}}else{if(h>maxSize){w=Math.round(w*maxSize/h);h=maxSize}}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve(c.toDataURL('image/jpeg',quality))};img.onerror=reject;img.src=e.target.result};reader.onerror=reject;reader.readAsDataURL(file)})}
let tempAnimalPhoto;
function setAnimalPhotoUI(dataURL){const img=document.getElementById('animalPhotoPreview'),ph=document.getElementById('animalPhotoPlaceholder'),rm=document.getElementById('animalPhotoRemove');if(!img)return;if(dataURL){img.src=dataURL;img.style.display='block';if(ph)ph.style.display='none';if(rm)rm.style.display='inline-block'}else{img.removeAttribute('src');img.style.display='none';if(ph)ph.style.display='block';if(rm)rm.style.display='none'}}
function resetAnimalPhoto(){tempAnimalPhoto=undefined;const inp=document.getElementById('animalPhotoInput');if(inp)inp.value='';setAnimalPhotoUI(null)}
function onAnimalPhoto(e){const f=e.target.files[0];if(!f)return;compressImage(f,500,0.7).then(d=>{tempAnimalPhoto=d;setAnimalPhotoUI(d)}).catch(()=>toast('Não foi possível ler a imagem','error'))}
function removeAnimalPhoto(){tempAnimalPhoto='';const inp=document.getElementById('animalPhotoInput');if(inp)inp.value='';setAnimalPhotoUI(null)}
function hydrateThumbs(){document.querySelectorAll('.ani-thumb[data-aid]:not([data-done])').forEach(el=>{el.setAttribute('data-done','1');photoGet(el.getAttribute('data-aid')).then(d=>{if(d){el.textContent='';el.style.backgroundImage=`url('${d}')`}})})}
function exportPhotos(){photoAll().then(obj=>{const n=Object.keys(obj).length;if(!n)return toast('Nenhuma foto para exportar','info');const blob=new Blob([JSON.stringify(obj)],{type:'application/json'});const a=document.createElement('a');const d=new Date();a.href=URL.createObjectURL(blob);a.download=`ELTECH_fotos_${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(n+' foto(s) exportada(s)!')})}
function importPhotos(e){const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=async ev=>{try{const obj=JSON.parse(ev.target.result);const keys=Object.keys(obj);for(const k of keys){await photoPut(k,obj[k])}toast(keys.length+' foto(s) importada(s)!');const pg=document.querySelector('.page.active');if(pg&&pg.id==='pageRebanho')renderLoteAnimals()}catch(err){toast('Arquivo inválido','error')}};reader.readAsText(file);e.target.value=''}

